class LocalCodeIntel:
    def __init__(
        self,
        workspace: Path,
        runtime_workspace: Path,
        *,
        excluded_dirs: set[str],
        text_suffixes: set[str],
        max_files: int,
    ) -> None:
        self.workspace = workspace.resolve()
        self.runtime_workspace = runtime_workspace.resolve()
        self.excluded_dirs = set(excluded_dirs)
        self.text_suffixes = set(text_suffixes)
        self.max_files = max_files
        self.cache_dir = self.runtime_workspace / ".cache" / "codeintel"
        self.cache_dir.mkdir(parents=True, exist_ok=True)
        self.cache_path = self.cache_dir / f"{_path_hash(self.workspace)}.json"
        self._cache: dict[str, Any] = {"workspace": self.workspace.as_posix(), "files": {}}
        self._loaded = False
        self._last_refresh = 0.0

    def _load_cache(self) -> None:
        if self._loaded:
            return
        if self.cache_path.exists():
            with suppress(Exception):
                self._cache = json.loads(self.cache_path.read_text(encoding="utf-8", errors="ignore"))
        self._loaded = True

    def _save_cache(self) -> None:
        self.cache_path.write_text(json.dumps(self._cache, ensure_ascii=True, indent=2), encoding="utf-8")

    def _iter_files(self) -> list[Path]:
        candidates: list[Path] = []
        for root, dirnames, filenames in os.walk(self.workspace, topdown=True):
            dirnames[:] = [dirname for dirname in dirnames if dirname not in self.excluded_dirs]
            root_path = Path(root)
            for filename in filenames:
                path = root_path / filename
                if path.suffix.lower() in self.text_suffixes:
                    candidates.append(path)
                    if len(candidates) >= self.max_files:
                        return candidates
        return candidates

    def _relative(self, path: Path) -> str:
        return path.resolve().relative_to(self.workspace).as_posix()

    @staticmethod
    def _symbol_container(scope: list[str]) -> str:
        return ".".join(scope) if scope else "<module>"

    def _parse_python(self, path: Path, text: str) -> dict[str, Any]:
        tree = ast.parse(text, filename=str(path))
        symbols: list[dict[str, Any]] = []
        references: list[dict[str, Any]] = []
        calls: list[dict[str, Any]] = []
        type_hints: list[dict[str, Any]] = []
        scope: list[str] = []

        class Visitor(ast.NodeVisitor):
            def visit_ClassDef(self, node: ast.ClassDef) -> None:
                container = self_outer._symbol_container(scope)
                symbols.append(
                    {
                        "name": node.name,
                        "qualified_name": ".".join([*scope, node.name]) if scope else node.name,
                        "kind": "class",
                        "line": node.lineno,
                        "end_line": getattr(node, "end_lineno", node.lineno),
                        "container": container,
                    }
                )
                scope.append(node.name)
                self.generic_visit(node)
                scope.pop()

            def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
                container = self_outer._symbol_container(scope)
                qualified = ".".join([*scope, node.name]) if scope else node.name
                symbols.append(
                    {
                        "name": node.name,
                        "qualified_name": qualified,
                        "kind": "method" if scope else "function",
                        "line": node.lineno,
                        "end_line": getattr(node, "end_lineno", node.lineno),
                        "container": container,
                    }
                )
                if node.returns is not None:
                    with suppress(Exception):
                        type_hints.append({"name": qualified, "type": ast.unparse(node.returns), "kind": "return"})
                for argument in [*node.args.args, *node.args.kwonlyargs]:
                    if argument.annotation is not None:
                        with suppress(Exception):
                            type_hints.append(
                                {
                                    "name": f"{qualified}.{argument.arg}",
                                    "type": ast.unparse(argument.annotation),
                                    "kind": "parameter",
                                }
                            )
                scope.append(node.name)
                self.generic_visit(node)
                scope.pop()

            def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef) -> None:
                self.visit_FunctionDef(node)

            def visit_AnnAssign(self, node: ast.AnnAssign) -> None:
                if isinstance(node.target, ast.Name):
                    with suppress(Exception):
                        type_hints.append(
                            {
                                "name": ".".join([*scope, node.target.id]) if scope else node.target.id,
                                "type": ast.unparse(node.annotation),
                                "kind": "variable",
                            }
                        )
                self.generic_visit(node)

            def visit_Name(self, node: ast.Name) -> None:
                references.append(
                    {
                        "name": node.id,
                        "line": node.lineno,
                        "column": node.col_offset + 1,
                        "context": type(node.ctx).__name__,
                        "container": self_outer._symbol_container(scope),
                    }
                )
                self.generic_visit(node)

            def visit_Call(self, node: ast.Call) -> None:
                callee = ""
                if isinstance(node.func, ast.Name):
                    callee = node.func.id
                elif isinstance(node.func, ast.Attribute):
                    callee = node.func.attr
                if callee:
                    calls.append(
                        {
                            "caller": self_outer._symbol_container(scope),
                            "callee": callee,
                            "line": node.lineno,
                        }
                    )
                self.generic_visit(node)

        self_outer = self
        Visitor().visit(tree)
        return {
            "symbols": symbols,
            "references": references,
            "calls": calls,
            "type_hints": type_hints,
        }

    def _parse_generic(self, path: Path, text: str) -> dict[str, Any]:
        symbols: list[dict[str, Any]] = []
        patterns = [
            (re.compile(r"^\s*class\s+([A-Za-z_][A-Za-z0-9_]*)"), "class"),
            (re.compile(r"^\s*(?:def|function)\s+([A-Za-z_][A-Za-z0-9_]*)"), "function"),
            (re.compile(r"^\s*(?:const|let|var|type|interface)\s+([A-Za-z_][A-Za-z0-9_]*)"), "symbol"),
        ]
        for index, line in enumerate(text.splitlines(), start=1):
            for pattern, kind in patterns:
                match = pattern.search(line)
                if match:
                    symbols.append(
                        {
                            "name": match.group(1),
                            "qualified_name": match.group(1),
                            "kind": kind,
                            "line": index,
                            "end_line": index,
                            "container": "<module>",
                        }
                    )
                    break
        return {"symbols": symbols, "references": [], "calls": [], "type_hints": []}

    def _refresh(self) -> None:
        self._load_cache()
        if time.time() - self._last_refresh < 2.0:
            return
        files = self._iter_files()
        cache_files = self._cache.setdefault("files", {})
        live: set[str] = set()
        changed = False
        for path in files:
            rel = self._relative(path)
            live.add(rel)
            stat = path.stat()
            cached = cache_files.get(rel)
            if cached and cached.get("mtime_ns") == stat.st_mtime_ns and cached.get("size") == stat.st_size:
                continue
            text = path.read_text(encoding="utf-8", errors="ignore")
            parsed = self._parse_python(path, text) if path.suffix.lower() == ".py" else self._parse_generic(path, text)
            cache_files[rel] = {
                "mtime_ns": stat.st_mtime_ns,
                "size": stat.st_size,
                "symbols": parsed["symbols"],
                "references": parsed["references"],
                "calls": parsed["calls"],
                "type_hints": parsed["type_hints"],
            }
            changed = True
        stale = [rel for rel in cache_files if rel not in live]
        for rel in stale:
            cache_files.pop(rel, None)
            changed = True
        if changed:
            self._save_cache()
        self._last_refresh = time.time()

    def document_symbols(self, path: str) -> dict[str, Any]:
        self._refresh()
        rel = self._relative((self.workspace / path).resolve()) if not Path(path).is_absolute() else self._relative(Path(path))
        data = self._cache["files"].get(rel, {})
        return {"path": rel, "symbols": data.get("symbols", [])}

    def workspace_symbols(self, query: str = "", max_results: int = 50) -> dict[str, Any]:
        self._refresh()
        normalized = query.strip().lower()
        results: list[dict[str, Any]] = []
        for rel, data in self._cache["files"].items():
            for symbol in data.get("symbols", []):
                haystack = f"{symbol['name']} {symbol.get('qualified_name', '')}".lower()
                if normalized and normalized not in haystack:
                    continue
                results.append({"path": rel, **symbol})
        results.sort(key=lambda item: (item["path"], item["line"], item["qualified_name"]))
        return {"query": query, "matches": results[:max_results]}

    def find_symbol_definitions(self, name: str, max_results: int = 50) -> dict[str, Any]:
        return self.workspace_symbols(query=name, max_results=max_results)

    def find_symbol_references(self, name: str, max_results: int = 100) -> dict[str, Any]:
        self._refresh()
        normalized = name.strip()
        if not normalized:
            return {"query": name, "matches": []}
        matches: list[dict[str, Any]] = []
        for rel, data in self._cache["files"].items():
            for reference in data.get("references", []):
                if reference.get("name") == normalized:
                    matches.append({"path": rel, **reference})
                    if len(matches) >= max_results:
                        return {"query": name, "matches": matches}
        token = re.compile(rf"\b{re.escape(normalized)}\b")
        for path in self._iter_files():
            rel = self._relative(path)
            if any(match["path"] == rel for match in matches):
                continue
            text = path.read_text(encoding="utf-8", errors="ignore")
            for line_number, line in enumerate(text.splitlines(), start=1):
                if token.search(line):
                    matches.append(
                        {
                            "path": rel,
                            "line": line_number,
                            "column": token.search(line).start() + 1 if token.search(line) else 1,
                            "context": "TextSearch",
                            "container": "<text-search>",
                        }
                    )
                    if len(matches) >= max_results:
                        return {"query": name, "matches": matches}
        return {"query": name, "matches": matches}

    def find_callers(self, name: str, max_results: int = 50) -> dict[str, Any]:
        self._refresh()
        normalized = name.strip()
        matches: list[dict[str, Any]] = []
        for rel, data in self._cache["files"].items():
            for call in data.get("calls", []):
                if call.get("callee") == normalized or call.get("callee", "").endswith(f".{normalized}"):
                    matches.append({"path": rel, **call})
        return {"query": name, "matches": matches[:max_results]}

    def find_callees(self, name: str, max_results: int = 50) -> dict[str, Any]:
        self._refresh()
        normalized = name.strip()
        matches: list[dict[str, Any]] = []
        for rel, data in self._cache["files"].items():
            for call in data.get("calls", []):
                if call.get("caller") == normalized or call.get("caller", "").endswith(f".{normalized}"):
                    matches.append({"path": rel, **call})
        return {"query": name, "matches": matches[:max_results]}

    def symbol_type_info(self, name: str, path: str | None = None) -> dict[str, Any]:
        self._refresh()
        normalized = name.strip()
        matches: list[dict[str, Any]] = []
        target_rel = ""
        if path:
            candidate = Path(path)
            target_rel = self._relative((self.workspace / candidate).resolve()) if not candidate.is_absolute() else self._relative(candidate)
        for rel, data in self._cache["files"].items():
            if target_rel and rel != target_rel:
                continue
            for hint in data.get("type_hints", []):
                if hint.get("name") == normalized or hint.get("name", "").endswith(f".{normalized}"):
                    matches.append({"path": rel, **hint})
        return {"query": name, "path": target_rel or None, "matches": matches}

    def pyright_diagnostics(self, path: str) -> dict[str, Any]:
        target = (self.workspace / path).resolve()
        executable = shutil.which("basedpyright") or shutil.which("pyright")
        if executable is None:
            return {"path": self._relative(target), "available": False, "diagnostics": []}
        completed = subprocess.run(
            [executable, "--outputjson", str(target)],
            capture_output=True,
            text=True,
            cwd=self.workspace,
            timeout=120,
            check=False,
        )
        output = completed.stdout.strip() or completed.stderr.strip()
        if not output:
            return {"path": self._relative(target), "available": True, "diagnostics": []}
        try:
            payload = json.loads(output)
        except Exception:
            return {"path": self._relative(target), "available": True, "diagnostics": [{"raw": _shorten(output, 4000)}]}
        return {
            "path": self._relative(target),
            "available": True,
            "summary": payload.get("summary", {}),
            "diagnostics": payload.get("generalDiagnostics", []),
        }


@dataclass
class SandboxRecord:
    sandbox_id: str
    kind: str
    root: Path
    workspace: Path
    created_at: str
    label: str = ""

    def to_dict(self) -> dict[str, Any]:
        return {
            "sandbox_id": self.sandbox_id,
            "kind": self.kind,
            "root": self.root.as_posix(),
            "workspace": self.workspace.as_posix(),
            "created_at": self.created_at,
            "label": self.label,
        }


class LocalSandboxManager:
    def __init__(self, workspace: Path, runtime_workspace: Path, excluded_dirs: set[str], base: Any | None = None) -> None:
        self.workspace = workspace.resolve()
        self.runtime_workspace = runtime_workspace.resolve()
        self.excluded_dirs = set(excluded_dirs)
        self.base = base
        self.root = self.runtime_workspace / ".cache" / "sandboxes"
        self.root.mkdir(parents=True, exist_ok=True)

    def _meta_path(self, sandbox_id: str) -> Path:
        return self.root / sandbox_id / "meta.json"

    def _load_record(self, sandbox_id: str) -> SandboxRecord:
        meta_path = self._meta_path(sandbox_id)
        if not meta_path.exists():
            raise FileNotFoundError(f"Unknown sandbox: {sandbox_id}")
        payload = json.loads(meta_path.read_text(encoding="utf-8", errors="ignore"))
        return SandboxRecord(
            sandbox_id=payload["sandbox_id"],
            kind=payload["kind"],
            root=Path(payload["root"]),
            workspace=Path(payload["workspace"]),
            created_at=payload["created_at"],
            label=payload.get("label", ""),
        )

    def _save_record(self, record: SandboxRecord) -> None:
        meta_path = self._meta_path(record.sandbox_id)
        meta_path.parent.mkdir(parents=True, exist_ok=True)
        meta_path.write_text(json.dumps(record.to_dict(), ensure_ascii=True, indent=2), encoding="utf-8")

    def list_sandboxes(self) -> list[dict[str, Any]]:
        sandboxes: list[dict[str, Any]] = []
        for meta_path in sorted(self.root.glob("*/meta.json")):
            with suppress(Exception):
                payload = json.loads(meta_path.read_text(encoding="utf-8", errors="ignore"))
                sandboxes.append(payload)
        return sandboxes

    def create(self, label: str = "", mode: str = "auto") -> dict[str, Any]:
        sandbox_id = uuid.uuid4().hex[:12]
        sandbox_root = self.root / sandbox_id / "workspace"
        requested = (mode or "auto").strip().lower()
        kind = "copy"
        git_dir = self.workspace / ".git"
        if requested in {"auto", "git", "worktree"} and git_dir.exists() and shutil.which("git"):
            completed = subprocess.run(
                ["git", "-C", str(self.workspace), "worktree", "add", "--detach", str(sandbox_root), "HEAD"],
                capture_output=True,
                text=True,
                timeout=180,
                check=False,
            )
            if completed.returncode == 0:
                kind = "git-worktree"
            elif requested in {"git", "worktree"}:
                raise RuntimeError(completed.stderr.strip() or completed.stdout.strip() or "git worktree add failed")
        if not sandbox_root.exists():
            ignore = shutil.ignore_patterns(*sorted(self.excluded_dirs | {".git"}))
            shutil.copytree(self.workspace, sandbox_root, ignore=ignore)
            kind = "copy"
        record = SandboxRecord(
            sandbox_id=sandbox_id,
            kind=kind,
            root=sandbox_root,
            workspace=self.workspace,
            created_at=_now_stamp(),
            label=label.strip(),
        )
        self._save_record(record)
        return record.to_dict()

    def _resolve(self, sandbox_id: str, candidate: str) -> tuple[SandboxRecord, Path]:
        record = self._load_record(sandbox_id)
        raw = Path(candidate.strip()).expanduser()
        target = raw.resolve() if raw.is_absolute() else (record.root / raw).resolve()
        if not target.is_relative_to(record.root):
            raise ValueError(f"Sandbox path escapes the sandbox root: {candidate}")
        return record, target

    def write_file(self, sandbox_id: str, path: str, content: str, make_parents: bool = True) -> dict[str, Any]:
        record, target = self._resolve(sandbox_id, path)
        if make_parents:
            target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        return {"sandbox_id": sandbox_id, "path": target.relative_to(record.root).as_posix(), "bytes_written": target.stat().st_size}

    def replace_text(self, sandbox_id: str, path: str, old_text: str, new_text: str, count: int = 0) -> dict[str, Any]:
        record, target = self._resolve(sandbox_id, path)
        original = target.read_text(encoding="utf-8", errors="ignore")
        replacements = original.count(old_text) if count == 0 else min(original.count(old_text), count)
        updated = original.replace(old_text, new_text, count) if count > 0 else original.replace(old_text, new_text)
        if updated != original:
            target.write_text(updated, encoding="utf-8")
        return {"sandbox_id": sandbox_id, "path": target.relative_to(record.root).as_posix(), "replacements": replacements}

    def delete_path(self, sandbox_id: str, path: str, recursive: bool = False) -> dict[str, Any]:
        record, target = self._resolve(sandbox_id, path)
        if target.is_dir():
            if recursive:
                shutil.rmtree(target)
            else:
                target.rmdir()
        else:
            target.unlink()
        return {"sandbox_id": sandbox_id, "deleted": target.relative_to(record.root).as_posix(), "recursive": recursive}

    def make_directory(self, sandbox_id: str, path: str) -> dict[str, Any]:
        record, target = self._resolve(sandbox_id, path)
        target.mkdir(parents=True, exist_ok=True)
        return {"sandbox_id": sandbox_id, "path": target.relative_to(record.root).as_posix(), "created": True}

    def move_path(self, sandbox_id: str, source: str, destination: str, overwrite: bool = False) -> dict[str, Any]:
        record, source_path = self._resolve(sandbox_id, source)
        _, destination_path = self._resolve(sandbox_id, destination)
        destination_path.parent.mkdir(parents=True, exist_ok=True)
        if destination_path.exists():
            if not overwrite:
                raise ValueError(f"Destination already exists: {destination}")
            if destination_path.is_dir():
                shutil.rmtree(destination_path)
            else:
                destination_path.unlink()
        shutil.move(str(source_path), str(destination_path))
        return {
            "sandbox_id": sandbox_id,
            "source": source_path.relative_to(record.root).as_posix(),
            "destination": destination_path.relative_to(record.root).as_posix(),
        }

    def run_command(self, sandbox_id: str, command: str, timeout_seconds: int = 120) -> dict[str, Any]:
        record = self._load_record(sandbox_id)
        payload = _run_shell_command(self.base, record.root, command, timeout_seconds)
        payload["sandbox_id"] = sandbox_id
        return payload

    def _copy_snapshot(self, root: Path) -> dict[str, str]:
        snapshot: dict[str, str] = {}
        for current_root, dirnames, filenames in os.walk(root, topdown=True):
            dirnames[:] = [dirname for dirname in dirnames if dirname not in self.excluded_dirs and dirname != ".git"]
            root_path = Path(current_root)
            for filename in filenames:
                path = root_path / filename
                rel = path.relative_to(root).as_posix()
                snapshot[rel] = hashlib.sha256(path.read_bytes()).hexdigest()
        return snapshot

    def _changed_entries(self, record: SandboxRecord) -> list[dict[str, Any]]:
        if record.kind == "git-worktree":
            completed = subprocess.run(
                ["git", "-C", str(record.root), "status", "--porcelain"],
                capture_output=True,
                text=True,
                timeout=120,
                check=False,
            )
            entries: list[dict[str, Any]] = []
            for line in completed.stdout.splitlines():
                if len(line) < 4:
                    continue
                entries.append({"status": line[:2].strip(), "path": line[3:].strip()})
            return entries
        before = self._copy_snapshot(record.workspace)
        after = self._copy_snapshot(record.root)
        changed: list[dict[str, Any]] = []
        all_paths = sorted(set(before) | set(after))
        for rel in all_paths:
            if rel not in before:
                changed.append({"status": "A", "path": rel})
            elif rel not in after:
                changed.append({"status": "D", "path": rel})
            elif before[rel] != after[rel]:
                changed.append({"status": "M", "path": rel})
        return changed

    def diff(self, sandbox_id: str, max_chars: int = LOCAL_ONLY_MAX_DIFF_CHARS) -> dict[str, Any]:
        record = self._load_record(sandbox_id)
        changed = self._changed_entries(record)
        chunks: list[str] = []
        for item in changed[:25]:
            rel = item["path"]
            original = record.workspace / rel
            modified = record.root / rel
            if original.exists() and modified.exists() and original.suffix.lower() in {".py", ".md", ".txt", ".json", ".toml", ".yaml", ".yml", ".js", ".ts"}:
                original_lines = original.read_text(encoding="utf-8", errors="ignore").splitlines()
                modified_lines = modified.read_text(encoding="utf-8", errors="ignore").splitlines()
                diff_text = "\n".join(
                    difflib.unified_diff(
                        original_lines,
                        modified_lines,
                        fromfile=original.as_posix(),
                        tofile=modified.as_posix(),
                        lineterm="",
                    )
                )
                if diff_text:
                    chunks.append(diff_text)
            else:
                chunks.append(f"{item['status']} {rel}")
            if sum(len(chunk) for chunk in chunks) >= max_chars:
                break
        return {
            "sandbox_id": sandbox_id,
            "kind": record.kind,
            "changed_files": changed,
            "diff": _shorten("\n\n".join(chunks), max_chars),
        }

    def apply_back(self, sandbox_id: str, overwrite: bool = True) -> dict[str, Any]:
        record = self._load_record(sandbox_id)
        changed = self._changed_entries(record)
        applied: list[dict[str, Any]] = []
        for item in changed:
            rel = item["path"]
            source = record.root / rel
            destination = record.workspace / rel
            status = item["status"]
            if status == "D":
                if destination.exists():
                    if destination.is_dir():
                        shutil.rmtree(destination)
                    else:
                        destination.unlink()
                applied.append({"path": rel, "action": "deleted"})
                continue
            destination.parent.mkdir(parents=True, exist_ok=True)
            if destination.exists() and not overwrite and status != "M":
                raise FileExistsError(rel)
            shutil.copy2(source, destination)
            applied.append({"path": rel, "action": "copied"})
        return {"sandbox_id": sandbox_id, "applied": applied}

    def destroy(self, sandbox_id: str) -> dict[str, Any]:
        record = self._load_record(sandbox_id)
        if record.kind == "git-worktree":
            subprocess.run(
                ["git", "-C", str(record.workspace), "worktree", "remove", "--force", str(record.root)],
                capture_output=True,
                text=True,
                timeout=120,
                check=False,
            )
        else:
            shutil.rmtree(record.root, ignore_errors=True)
        shutil.rmtree(self.root / sandbox_id, ignore_errors=True)
        return {"sandbox_id": sandbox_id, "destroyed": True}


def _resolve_unique_workspace_file_by_basename(
    workspace: Path,
    candidate: str,
    *,
    allowed_suffixes: set[str] | None = None,
) -> Path | None:
    root = workspace.resolve()
    normalized = str(candidate or "").strip().strip("\"'").replace("\\", "/")
    if (
        not normalized
        or "://" in normalized
        or Path(normalized).expanduser().is_absolute()
        or re.match(r"^[A-Za-z]:[\\/]", normalized)
    ):
        return None
    basename = Path(normalized).name
    if not basename or basename in {".", ".."}:
        return None
    suffixes = {str(item).lower() for item in (allowed_suffixes or set())}
    if suffixes and Path(basename).suffix.lower() not in suffixes:
        return None

    excluded_directories = {
        ".cache",
        ".git",
        ".memory",
        ".ruff_cache",
        ".venv",
        ".venv312",
        "__pycache__",
        "models",
        "node_modules",
    }
    matches: list[Path] = []
    try:
        for current_root, directory_names, file_names in os.walk(root):
            directory_names[:] = [
                name for name in directory_names if name.casefold() not in excluded_directories
            ]
            for file_name in file_names:
                if file_name.casefold() != basename.casefold():
                    continue
                resolved = (Path(current_root) / file_name).resolve()
                resolved.relative_to(root)
                if not resolved.is_file():
                    continue
                matches.append(resolved)
                if len(matches) > 1:
                    return None
    except (OSError, ValueError):
        return None
    return matches[0] if len(matches) == 1 else None

class LocalMCPServerManager:
    def __init__(self, workspace: Path, runtime_workspace: Path, base: Any | None = None) -> None:
        self.workspace = workspace.resolve()
        self.runtime_workspace = runtime_workspace.resolve()
        self.base = base
        self.root = self.runtime_workspace / ".cache" / "mcp_servers"
        self.root.mkdir(parents=True, exist_ok=True)
        self._mcp_python_probe_cache: dict[str, tuple[bool, str]] = {}

    def _meta_path(self, server_id: str) -> Path:
        return self.root / server_id / "meta.json"

    def _write_meta(self, server_id: str, payload: dict[str, Any]) -> None:
        path = self._meta_path(server_id)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(payload, ensure_ascii=True, indent=2), encoding="utf-8")

    def _read_meta(self, server_id: str) -> dict[str, Any]:
        raw_server_id = str(server_id or "").strip().lower()
        normalized_server_id = re.sub(r"[\s_-]+", "", raw_server_id)
        if not re.fullmatch(r"[a-f0-9]{12}", normalized_server_id):
            raise ValueError(
                "server_id must be a 12-character hexadecimal id; optional spaces, hyphens, "
                "or underscores are ignored."
            )
        server_id = normalized_server_id
        path = self._meta_path(server_id)
        if not path.exists():
            raise FileNotFoundError(server_id)
        return json.loads(path.read_text(encoding="utf-8", errors="ignore"))

    def _refresh_status(self, payload: dict[str, Any]) -> dict[str, Any]:
        pid = int(payload.get("pid") or 0)
        if pid <= 0:
            return payload
        with suppress(Exception):
            os.kill(pid, 0)
            return payload
        if payload.get("status") not in {"stopped", "failed"}:
            payload["status"] = "stopped"
            payload["finished_at"] = payload.get("finished_at") or _now_stamp()
            self._write_meta(str(payload["server_id"]), payload)
        return payload

    def _resolve_workspace_path(self, workspace: Path, candidate: str, *, allow_missing: bool = True) -> Path:
        if self.base is not None and hasattr(self.base, "resolve_workspace_path"):
            return self.base.resolve_workspace_path(
                workspace,
                candidate,
                allow_missing=allow_missing,
                allow_external=True,
            )
        normalized = candidate.strip()
        if "\\" in normalized and not re.match(r"^[A-Za-z]:[\\/]", normalized):
            normalized = normalized.replace("\\", "/")
        raw = Path(normalized).expanduser()
        resolved = raw.resolve() if raw.is_absolute() else (workspace / raw).resolve()
        if not allow_missing and not resolved.exists():
            raise FileNotFoundError(candidate)
        return resolved

    def _resolve_python(self, workspace: Path, python_path: str | None = None) -> Path:
        if python_path:
            return self._resolve_workspace_path(workspace, python_path, allow_missing=False)
        preferred = _preferred_project_python(workspace)
        if preferred is not None:
            return preferred.absolute()
        return Path(sys.executable).absolute()

    def _probe_mcp_python(self, workspace: Path, python_path: Path) -> tuple[bool, str]:
        key = str(python_path.absolute()).replace("\\", "/").casefold()
        cached = self._mcp_python_probe_cache.get(key)
        if cached is not None:
            return cached
        try:
            completed = self._run_python(
                workspace,
                python_path,
                [
                    "-I",
                    "-c",
                    "import mcp; print('QUBITZ_MCP_CLIENT_READY')",
                ],
                timeout_seconds=20,
            )
        except Exception as exc:
            result = (False, f"{type(exc).__name__}: {exc}")
        else:
            stdout = completed.stdout or ""
            stderr = completed.stderr or ""
            if completed.returncode == 0 and "QUBITZ_MCP_CLIENT_READY" in stdout:
                result = (True, "")
            else:
                result = (
                    False,
                    _shorten(stderr or stdout or f"interpreter exited with {completed.returncode}", 1000),
                )
        self._mcp_python_probe_cache[key] = result
        return result

    def _resolve_mcp_python(self, workspace: Path, python_path: str | None = None) -> Path:
        if python_path:
            explicit = self._resolve_workspace_path(workspace, python_path, allow_missing=False)
            ready, reason = self._probe_mcp_python(workspace, explicit)
            if ready:
                return explicit.absolute()
            raise RuntimeError(
                f"The requested Python interpreter cannot run the MCP client: {explicit}. {reason}"
            )

        project_candidates = list(_project_environment_candidates(workspace))
        candidates: list[Path] = []
        preferred = _preferred_project_python(workspace)
        if preferred is not None:
            candidates.append(preferred)
        candidates.extend(interpreter for _root, interpreter, _layout in project_candidates)
        if not candidates:
            candidates.append(Path(sys.executable))

        failures: list[str] = []
        seen: set[str] = set()
        for candidate in candidates:
            key = str(candidate.absolute()).replace("\\", "/").casefold()
            if key in seen or not candidate.exists():
                continue
            seen.add(key)
            ready, reason = self._probe_mcp_python(workspace, candidate)
            if ready:
                return candidate.absolute()
            failures.append(f"{candidate}: {reason}")
        detail = "; ".join(failures[:4]) or "no executable project Python candidate was found"
        raise RuntimeError(
            "No verified MCP-capable Python interpreter is available for the active project. "
            f"Install the MCP package into the intended project environment after user approval. Probes: {detail}"
        )

    def _normalize_env(self, env: dict[str, str] | None = None) -> dict[str, str]:
        merged = {}
        if env:
            for key, value in env.items():
                normalized_key = str(key).strip()
                if normalized_key:
                    merged[normalized_key] = str(value)
        merged.setdefault("QUBITZ_ALLOW_EMBED_ONLINE", "1")
        return merged

    def _maybe_windows_arg(self, workspace: Path, value: str) -> str:
        if not callable(getattr(self.base, "in_wsl", None)) or not self.base.in_wsl():
            return value
        if isinstance(getattr(self.base, "WINDOWS_DRIVE_PATH_PATTERN", None), re.Pattern):
            if self.base.WINDOWS_DRIVE_PATH_PATTERN.match(value):
                return value.replace("/", "\\")
        candidate = Path(value).expanduser()
        resolved: Path | None = None
        if candidate.is_absolute():
            resolved = candidate.resolve()
        else:
            local_candidate = (workspace / candidate).resolve()
            if local_candidate.exists():
                resolved = local_candidate
        if resolved is None:
            return value
        translator = getattr(self.base, "wsl_path_to_windows", None)
        if callable(translator):
            translated = translator(resolved)
            if translated:
                return str(translated)
        fallback = getattr(self.base, "wsl_path_to_windows_path", None)
        if callable(fallback):
            return str(fallback(resolved))
        return str(resolved)

    def _build_python_command(self, workspace: Path, python_path: Path, arguments: Sequence[str]) -> list[str]:
        command = [str(python_path), *[str(item) for item in arguments]]
        if (
            callable(getattr(self.base, "in_wsl", None))
            and self.base.in_wsl()
            and shutil.which("powershell.exe") is not None
            and str(python_path).lower().endswith(".exe")
        ):
            workspace_windows = _workspace_windows_path(self.base, workspace)
            translated = [self._maybe_windows_arg(workspace, part) for part in command]
            script_lines = [
                "$ProgressPreference = 'SilentlyContinue'",
                f"Set-Location -LiteralPath {_powershell_single_quote(workspace_windows)}",
                "& " + " ".join(_powershell_single_quote(part) for part in translated),
            ]
            return ["powershell.exe", "-NoProfile", "-Command", "; ".join(script_lines)]
        return command

    def _run_python(
        self,
        workspace: Path,
        python_path: Path,
        arguments: Sequence[str],
        *,
        env: dict[str, str] | None = None,
        timeout_seconds: int = 120,
    ) -> subprocess.CompletedProcess[str]:
        merged_env = os.environ.copy()
        merged_env.update(self._normalize_env(env))
        command = self._build_python_command(workspace, python_path, arguments)
        return subprocess.run(
            command,
            cwd=workspace,
            capture_output=True,
            text=True,
            timeout=max(1, timeout_seconds),
            check=False,
            env=merged_env,
        )

    def _popen_python(
        self,
        workspace: Path,
        python_path: Path,
        arguments: Sequence[str],
        *,
        env: dict[str, str] | None = None,
        log_path: Path,
    ) -> tuple[subprocess.Popen[str], list[str]]:
        merged_env = os.environ.copy()
        merged_env.update(self._normalize_env(env))
        command = self._build_python_command(workspace, python_path, arguments)
        log_path.parent.mkdir(parents=True, exist_ok=True)
        log_handle = log_path.open("w", encoding="utf-8", errors="ignore")
        try:
            process = subprocess.Popen(
                command,
                cwd=workspace,
                stdout=log_handle,
                stderr=subprocess.STDOUT,
                stdin=subprocess.DEVNULL,
                text=True,
                env=merged_env,
            )
        except Exception:
            log_handle.close()
            raise
        return process, command

    def _resolve_reference(self, workspace: Path, server_reference: str) -> Path | str:
        reference = server_reference.strip()
        if not reference:
            raise ValueError("server_reference must not be empty.")
        if "\n" in reference or "\r" in reference:
            raise ValueError(
                "server_reference must be a URL, script path, or .mcp.json path, not inline script text."
            )
        if "://" in reference:
            return reference
        resolved = self._resolve_workspace_path(workspace, reference, allow_missing=True)
        if resolved.exists():
            return resolved
        recovered = _resolve_unique_workspace_file_by_basename(
            self.workspace,
            reference,
            allowed_suffixes={".py", ".json", ".exe", ".bat", ".cmd", ".ps1", ".sh"},
        )
        if recovered is not None:
            return recovered
        raise FileNotFoundError(server_reference)

    def _probe_tools(
        self,
        workspace: Path,
        *,
        server_reference: str,
        python_path: Path,
        env: dict[str, str] | None = None,
        timeout_seconds: int = 30,
    ) -> dict[str, Any]:
        reference = self._resolve_reference(workspace, server_reference)
        reference_mode = "path" if isinstance(reference, Path) else "text"
        reference_value = str(reference)
        script = textwrap.dedent(
            """
            import asyncio
            import json
            import os
            import sys
            from contextlib import asynccontextmanager
            from pathlib import Path
            from mcp import ClientSession, StdioServerParameters
            from mcp.client.stdio import stdio_client
            from mcp.client.streamable_http import streamable_http_client

            BEGIN = "QUBITZ_JSON_BEGIN"
            END = "QUBITZ_JSON_END"

            @asynccontextmanager
            async def open_session(ref_mode: str, ref_value: str):
                if ref_mode == "text":
                    async with streamable_http_client(ref_value) as (read, write, _):
                        async with ClientSession(read, write) as session:
                            await session.initialize()
                            yield session
                    return
                path = Path(ref_value)
                if path.suffix.lower() == ".json":
                    config = json.loads(path.read_text(encoding="utf-8"))
                    servers = config.get("mcpServers", config)
                    if not isinstance(servers, dict) or len(servers) != 1:
                        raise ValueError("The MCP config must contain exactly one server entry.")
                    entry = next(iter(servers.values()))
                    command = str(entry["command"])
                    args = [str(item) for item in entry.get("args", [])]
                    env = os.environ.copy()
                    env.update({str(key): str(value) for key, value in entry.get("env", {}).items()})
                    cwd = entry.get("cwd") or str(path.parent)
                else:
                    command = sys.executable if path.suffix.lower() == ".py" else str(path)
                    args = [str(path)] if path.suffix.lower() == ".py" else []
                    env = None
                    cwd = str(path.parent)
                parameters = StdioServerParameters(command=command, args=args, env=env, cwd=cwd)
                async with stdio_client(parameters) as (read, write):
                    async with ClientSession(read, write) as session:
                        await session.initialize()
                        yield session

            async def main() -> None:
                ref_mode = sys.argv[1]
                ref_value = sys.argv[2]
                async with open_session(ref_mode, ref_value) as session:
                    response = await session.list_tools()
                    tools = response.tools
                serialized = []
                for tool in tools:
                    if hasattr(tool, "model_dump"):
                        item = tool.model_dump()
                    elif hasattr(tool, "dict"):
                        item = tool.dict()
                    else:
                        item = {"repr": repr(tool)}
                    if "name" not in item and hasattr(tool, "name"):
                        item["name"] = getattr(tool, "name")
                    serialized.append(item)
                print(BEGIN)
                print(json.dumps({"count": len(serialized), "tools": serialized}, ensure_ascii=False))
                print(END)

            asyncio.run(main())
            """
        ).strip()
        completed = self._run_python(
            workspace,
            python_path,
            ["-c", script, reference_mode, reference_value],
            env=env,
            timeout_seconds=timeout_seconds,
        )
        stdout = completed.stdout or ""
        stderr = completed.stderr or ""
        begin = stdout.find("QUBITZ_JSON_BEGIN")
        end = stdout.find("QUBITZ_JSON_END")
        if completed.returncode == 0 and begin != -1 and end != -1 and end > begin:
            json_text = stdout[begin + len("QUBITZ_JSON_BEGIN") : end].strip()
            payload = json.loads(json_text)
            return {
                "reference": reference_value,
                "count": int(payload.get("count") or 0),
                "tools": payload.get("tools") or [],
                "returncode": completed.returncode,
                "stdout": _shorten(stdout, 12000),
                "stderr": _shorten(stderr, 12000),
            }
        raise RuntimeError(_shorten(stderr or stdout or "Failed to probe MCP tools.", 4000))

    def _invoke_tool(
        self,
        workspace: Path,
        *,
        server_reference: str,
        python_path: Path,
        tool_name: str,
        arguments: dict[str, Any] | None = None,
        env: dict[str, str] | None = None,
        timeout_seconds: int = 30,
    ) -> dict[str, Any]:
        reference = self._resolve_reference(workspace, server_reference)
        reference_mode = "path" if isinstance(reference, Path) else "text"
        reference_value = str(reference)
        script = textwrap.dedent(
            """
            import asyncio
            import json
            import os
            import sys
            from contextlib import asynccontextmanager
            from pathlib import Path
            from mcp import ClientSession, StdioServerParameters
            from mcp.client.stdio import stdio_client
            from mcp.client.streamable_http import streamable_http_client

            BEGIN = "QUBITZ_JSON_BEGIN"
            END = "QUBITZ_JSON_END"

            @asynccontextmanager
            async def open_session(ref_mode: str, ref_value: str):
                if ref_mode == "text":
                    async with streamable_http_client(ref_value) as (read, write, _):
                        async with ClientSession(read, write) as session:
                            await session.initialize()
                            yield session
                    return
                path = Path(ref_value)
                if path.suffix.lower() == ".json":
                    config = json.loads(path.read_text(encoding="utf-8"))
                    servers = config.get("mcpServers", config)
                    if not isinstance(servers, dict) or len(servers) != 1:
                        raise ValueError("The MCP config must contain exactly one server entry.")
                    entry = next(iter(servers.values()))
                    command = str(entry["command"])
                    args = [str(item) for item in entry.get("args", [])]
                    env = os.environ.copy()
                    env.update({str(key): str(value) for key, value in entry.get("env", {}).items()})
                    cwd = entry.get("cwd") or str(path.parent)
                else:
                    command = sys.executable if path.suffix.lower() == ".py" else str(path)
                    args = [str(path)] if path.suffix.lower() == ".py" else []
                    env = None
                    cwd = str(path.parent)
                parameters = StdioServerParameters(command=command, args=args, env=env, cwd=cwd)
                async with stdio_client(parameters) as (read, write):
                    async with ClientSession(read, write) as session:
                        await session.initialize()
                        yield session

            async def main() -> None:
                ref_mode, ref_value, tool_name, arguments_json = sys.argv[1:5]
                arguments = json.loads(arguments_json)
                async with open_session(ref_mode, ref_value) as session:
                    result = await session.call_tool(tool_name, arguments)
                if hasattr(result, "model_dump"):
                    serialized = result.model_dump(mode="json")
                elif hasattr(result, "dict"):
                    serialized = result.dict()
                else:
                    serialized = {"repr": repr(result)}
                print(BEGIN)
                print(json.dumps({"tool": tool_name, "result": serialized}, ensure_ascii=False))
                print(END)

            asyncio.run(main())
            """
        ).strip()
        completed = self._run_python(
            workspace,
            python_path,
            [
                "-c",
                script,
                reference_mode,
                reference_value,
                tool_name,
                json.dumps(arguments or {}, ensure_ascii=True),
            ],
            env=env,
            timeout_seconds=timeout_seconds,
        )
        stdout = completed.stdout or ""
        stderr = completed.stderr or ""
        begin = stdout.find("QUBITZ_JSON_BEGIN")
        end = stdout.find("QUBITZ_JSON_END")
        if completed.returncode == 0 and begin != -1 and end != -1 and end > begin:
            json_text = stdout[begin + len("QUBITZ_JSON_BEGIN") : end].strip()
            payload = json.loads(json_text)
            return {
                "reference": reference_value,
                "tool": tool_name,
                "result": payload.get("result"),
                "returncode": completed.returncode,
                "stdout": _shorten(stdout, 12000),
                "stderr": _shorten(stderr, 12000),
            }
        raise RuntimeError(_shorten(stderr or stdout or f"Failed to invoke MCP tool {tool_name!r}.", 4000))

    def start_server(
        self,
        server_script: str,
        *,
        cwd: str = ".",
        python_path: str | None = None,
        arguments: list[str] | None = None,
        env: dict[str, str] | None = None,
        name: str = "",
        connection_uri: str = "",
        ready_substring: str = "",
        wait_seconds: int = 15,
    ) -> dict[str, Any]:
        workspace = self._resolve_workspace_path(self.workspace, cwd, allow_missing=False)
        script_resolution = "direct"
        script_path = self._resolve_workspace_path(workspace, server_script, allow_missing=True)
        if not script_path.exists():
            recovered = _resolve_unique_workspace_file_by_basename(
                self.workspace,
                server_script,
                allowed_suffixes={".py", ".exe", ".bat", ".cmd", ".ps1", ".sh"},
            )
            if recovered is None:
                raise FileNotFoundError(server_script)
            script_path = recovered
            script_resolution = "unique_workspace_basename"
        interpreter = self._resolve_python(workspace, python_path)
        mcp_client_interpreter = (
            self._resolve_mcp_python(workspace)
            if connection_uri.strip()
            else interpreter
        )
        server_id = uuid.uuid4().hex[:12]
        log_path = self.root / server_id / "server.log"
        process, command = self._popen_python(
            workspace,
            interpreter,
            [str(script_path), *[str(item) for item in (arguments or [])]],
            env=env,
            log_path=log_path,
        )
        metadata = {
            "server_id": server_id,
            "name": (name or script_path.stem).strip() or script_path.stem,
            "status": "starting",
            "pid": process.pid,
            "workspace": workspace.as_posix(),
            "runtime_workspace": self.runtime_workspace.as_posix(),
            "server_script": script_path.as_posix(),
            "requested_server_script": str(server_script),
            "server_script_resolution": script_resolution,
            "python_path": interpreter.as_posix(),
            "arguments": [str(item) for item in (arguments or [])],
            "environment": self._normalize_env(env),
            "command": command,
            "connection_uri": connection_uri.strip(),
            "ready_substring": ready_substring.strip(),
            "created_at": _now_stamp(),
            "finished_at": None,
            "returncode": None,
            "log_path": log_path.as_posix(),
        }
        self._write_meta(server_id, metadata)
        deadline = time.time() + max(0, wait_seconds)
        while time.time() < deadline:
            if process.poll() is not None:
                metadata["status"] = "failed"
                metadata["returncode"] = process.returncode
                metadata["finished_at"] = _now_stamp()
                self._write_meta(server_id, metadata)
                log_text = ""
                if log_path.exists():
                    log_text = _shorten(log_path.read_text(encoding="utf-8", errors="ignore"), 4000)
                raise RuntimeError(log_text or f"Server exited early with return code {process.returncode}.")
            if metadata["connection_uri"]:
                try:
                    self._probe_tools(
                        workspace,
                        server_reference=metadata["connection_uri"],
                        python_path=mcp_client_interpreter,
                        env=env,
                        timeout_seconds=10,
                    )
                    metadata["status"] = "ready"
                    self._write_meta(server_id, metadata)
                    return metadata
                except Exception:
                    pass
            elif metadata["ready_substring"]:
                with suppress(Exception):
                    log_text = log_path.read_text(encoding="utf-8", errors="ignore")
                    if metadata["ready_substring"] in log_text:
                        metadata["status"] = "ready"
                        self._write_meta(server_id, metadata)
                        return metadata
            else:
                time.sleep(1.0)
                metadata["status"] = "running"
                self._write_meta(server_id, metadata)
                return metadata
            time.sleep(0.5)
        metadata["status"] = "running"
        self._write_meta(server_id, metadata)
        return metadata

    def list_tools(
        self,
        *,
        server_id: str = "",
        server_reference: str = "",
        cwd: str = ".",
        python_path: str | None = None,
        timeout_seconds: int = 30,
    ) -> dict[str, Any]:
        if server_id:
            metadata = self._refresh_status(self._read_meta(server_id))
            workspace = Path(metadata["workspace"])
            interpreter = self._resolve_mcp_python(workspace, python_path)
            reference = server_reference.strip() or metadata.get("connection_uri") or metadata.get("server_script") or ""
            env = metadata.get("environment") or {}
        else:
            workspace = self._resolve_workspace_path(self.workspace, cwd, allow_missing=False)
            interpreter = self._resolve_mcp_python(workspace, python_path)
            reference = server_reference.strip()
            env = None
        if not reference:
            raise ValueError("Provide server_id or server_reference.")
        payload = self._probe_tools(
            workspace,
            server_reference=reference,
            python_path=interpreter,
            env=env,
            timeout_seconds=timeout_seconds,
        )
        if server_id:
            payload["server_id"] = server_id
        return payload

    def call_tool(
        self,
        *,
        tool_name: str,
        arguments: dict[str, Any] | None = None,
        server_id: str = "",
        server_reference: str = "",
        cwd: str = ".",
        python_path: str | None = None,
        timeout_seconds: int = 30,
    ) -> dict[str, Any]:
        if not tool_name.strip():
            raise ValueError("tool_name must not be empty.")
        if server_id:
            metadata = self._refresh_status(self._read_meta(server_id))
            workspace = Path(metadata["workspace"])
            interpreter = self._resolve_mcp_python(workspace, python_path)
            reference = server_reference.strip() or metadata.get("connection_uri") or metadata.get("server_script") or ""
            env = metadata.get("environment") or {}
        else:
            workspace = self._resolve_workspace_path(self.workspace, cwd, allow_missing=False)
            interpreter = self._resolve_mcp_python(workspace, python_path)
            reference = server_reference.strip()
            env = None
        if not reference:
            raise ValueError("Provide server_id or server_reference.")
        payload = self._invoke_tool(
            workspace,
            server_reference=reference,
            python_path=interpreter,
            tool_name=tool_name.strip(),
            arguments=arguments,
            env=env,
            timeout_seconds=timeout_seconds,
        )
        if server_id:
            payload["server_id"] = server_id
        return payload

    def stop_server(self, server_id: str) -> dict[str, Any]:
        metadata = self._read_meta(server_id)
        pid = int(metadata.get("pid") or 0)
        stopped = False
        if pid > 0:
            if (
                callable(getattr(self.base, "in_wsl", None))
                and self.base.in_wsl()
                and shutil.which("taskkill.exe") is not None
            ):
                with suppress(Exception):
                    completed = subprocess.run(
                        ["taskkill.exe", "/PID", str(pid), "/T", "/F"],
                        capture_output=True,
                        text=True,
                        timeout=30,
                        check=False,
                    )
                    stopped = completed.returncode == 0
            if not stopped:
                with suppress(Exception):
                    os.kill(pid, 15)
                    stopped = True
        metadata["status"] = "stopped"
        metadata["finished_at"] = _now_stamp()
        self._write_meta(server_id, metadata)
        return {"server_id": server_id, "stopped": stopped}

    def read_log(self, server_id: str, max_chars: int = 12000) -> dict[str, Any]:
        metadata = self._refresh_status(self._read_meta(server_id))
        log_path = Path(metadata["log_path"])
        log_text = ""
        if log_path.exists():
            log_text = _shorten(log_path.read_text(encoding="utf-8", errors="ignore"), max_chars)
        return {"meta": metadata, "log": log_text}


class LocalBackgroundJobManager:
    def __init__(self, runtime_workspace: Path, launch_script: Path) -> None:
        self.runtime_workspace = runtime_workspace.resolve()
        self.launch_script = launch_script.resolve()
        self.root = self.runtime_workspace / ".cache" / "background_jobs"
        self.root.mkdir(parents=True, exist_ok=True)

    def _meta_path(self, job_id: str) -> Path:
        return self.root / job_id / "meta.json"

    def _write_meta(self, job_id: str, payload: dict[str, Any]) -> None:
        path = self._meta_path(job_id)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(payload, ensure_ascii=True, indent=2), encoding="utf-8")

    def _read_meta(self, job_id: str) -> dict[str, Any]:
        path = self._meta_path(job_id)
        if not path.exists():
            raise FileNotFoundError(job_id)
        return json.loads(path.read_text(encoding="utf-8", errors="ignore"))

    def _build_command(self, config: Any, workspace: Path, prompt: str) -> list[str]:
        command = [sys.executable, str(self.launch_script), "--cli", "--workspace", str(workspace), "--prompt", prompt]
        with suppress(Exception):
            command.extend(["--max-steps", str(getattr(config, "max_steps"))])
        if hasattr(config, "model_name"):
            command.extend(["--model", str(getattr(config, "model_name"))])
        if hasattr(config, "embed_model_name"):
            command.extend(["--embed-model", str(getattr(config, "embed_model_name"))])
        if hasattr(config, "ollama_num_ctx"):
            command.extend(["--num-ctx", str(getattr(config, "ollama_num_ctx"))])
        elif hasattr(config, "num_ctx"):
            command.extend(["--num-ctx", str(getattr(config, "num_ctx"))])
        if hasattr(config, "ollama_num_predict"):
            command.extend(["--num-predict", str(getattr(config, "ollama_num_predict"))])
        elif hasattr(config, "num_predict"):
            command.extend(["--num-predict", str(getattr(config, "num_predict"))])
        if hasattr(config, "model_path") and getattr(config, "model_path"):
            command.extend(["--model-path", str(getattr(config, "model_path"))])
        if hasattr(config, "server_url") and getattr(config, "server_url"):
            command.extend(["--server-url", str(getattr(config, "server_url"))])
        if hasattr(config, "llama_server_path") and getattr(config, "llama_server_path"):
            command.extend(["--llama-server", str(getattr(config, "llama_server_path"))])
        return command

    def start(
        self,
        prompt: str,
        *,
        config: Any,
        workspace: Path,
        sandbox_id: str | None = None,
    ) -> dict[str, Any]:
        job_id = uuid.uuid4().hex[:12]
        job_dir = self.root / job_id
        job_dir.mkdir(parents=True, exist_ok=True)
        log_path = job_dir / "job.log"
        command = self._build_command(config, workspace, prompt)
        env = os.environ.copy()
        env.setdefault("QUBITZ_ALLOW_EMBED_ONLINE", "1")
        env["QUBITZ_BACKGROUND_JOB"] = "1"
        with log_path.open("w", encoding="utf-8", errors="ignore") as handle:
            process = subprocess.Popen(
                command,
                cwd=self.runtime_workspace,
                stdout=handle,
                stderr=subprocess.STDOUT,
                stdin=subprocess.DEVNULL,
                text=True,
                env=env,
            )
        meta = {
            "job_id": job_id,
            "status": "running",
            "prompt": prompt,
            "workspace": workspace.as_posix(),
            "runtime_workspace": self.runtime_workspace.as_posix(),
            "sandbox_id": sandbox_id,
            "pid": process.pid,
            "command": command,
            "launch_script": self.launch_script.as_posix(),
            "created_at": _now_stamp(),
            "finished_at": None,
            "returncode": None,
            "log_path": log_path.as_posix(),
        }
        self._write_meta(job_id, meta)

        def _watch() -> None:
            returncode = process.wait()
            latest = self._read_meta(job_id)
            latest["status"] = "completed" if returncode == 0 else "failed"
            latest["finished_at"] = _now_stamp()
            latest["returncode"] = returncode
            self._write_meta(job_id, latest)

        threading.Thread(target=_watch, daemon=True).start()
        return meta
    def start_command(
        self,
        command: Sequence[str],
        *,
        workspace: Path,
        label: str,
        wait_seconds: float = PROJECT_LAUNCH_READY_WAIT_SECONDS,
    ) -> dict[str, Any]:
        normalized_command = [str(item) for item in command if str(item)]
        if not normalized_command:
            raise ValueError("Project launch command must not be empty.")
        job_id = uuid.uuid4().hex[:12]
        job_dir = self.root / job_id
        job_dir.mkdir(parents=True, exist_ok=True)
        log_path = job_dir / "job.log"
        env = os.environ.copy()
        env["QUBITZ_PROJECT_LAUNCH"] = "1"
        with log_path.open("w", encoding="utf-8", errors="ignore") as handle:
            process = subprocess.Popen(
                normalized_command,
                cwd=workspace,
                stdout=handle,
                stderr=subprocess.STDOUT,
                stdin=subprocess.DEVNULL,
                text=True,
                env=env,
                start_new_session=os.name != "nt",
            )
        meta = {
            "job_id": job_id,
            "job_type": "project_launch",
            "status": "starting",
            "label": label,
            "workspace": workspace.as_posix(),
            "runtime_workspace": self.runtime_workspace.as_posix(),
            "pid": process.pid,
            "command": normalized_command,
            "created_at": _now_stamp(),
            "finished_at": None,
            "returncode": None,
            "log_path": log_path.as_posix(),
            "detected_urls": [],
        }
        self._write_meta(job_id, meta)
        deadline = time.time() + max(0.0, float(wait_seconds))
        while time.time() < deadline and process.poll() is None:
            time.sleep(0.1)
        returncode = process.poll()
        if returncode is None:
            meta["status"] = "running"
        else:
            meta["status"] = "completed" if returncode == 0 else "failed"
            meta["returncode"] = returncode
            meta["finished_at"] = _now_stamp()
        log_text = ""
        with suppress(Exception):
            log_text = log_path.read_text(encoding="utf-8", errors="ignore")
        if PROJECT_LAUNCH_FATAL_LOG_PATTERN.search(log_text):
            returncode = process.poll()
            meta["status"] = "failed"
            meta["returncode"] = returncode
            if returncode is not None:
                meta["finished_at"] = _now_stamp()
            meta["startup_error_detected"] = True
        meta["detected_urls"] = list(dict.fromkeys(PROJECT_LAUNCH_LOCAL_URL_PATTERN.findall(log_text)))[:8]
        self._write_meta(job_id, meta)

        if returncode is None:
            def _watch() -> None:
                completed_code = process.wait()
                latest = self._read_meta(job_id)
                if latest.get("status") not in {"cancelling", "cancelled"}:
                    latest["status"] = "completed" if completed_code == 0 else "failed"
                    latest["finished_at"] = _now_stamp()
                    latest["returncode"] = completed_code
                    self._write_meta(job_id, latest)

            threading.Thread(target=_watch, daemon=True).start()
        result = dict(meta)
        result["log_excerpt"] = _shorten(log_text.strip(), 2000)
        return result

    def list_jobs(self) -> list[dict[str, Any]]:
        jobs: list[dict[str, Any]] = []
        for meta_path in sorted(self.root.glob("*/meta.json")):
            with suppress(Exception):
                jobs.append(json.loads(meta_path.read_text(encoding="utf-8", errors="ignore")))
        jobs.sort(key=lambda item: item.get("created_at", ""), reverse=True)
        return jobs

    def read_job(self, job_id: str, max_chars: int = 12000) -> dict[str, Any]:
        meta = self._read_meta(job_id)
        log_text = ""
        log_path = Path(meta["log_path"])
        if log_path.exists():
            log_text = _shorten(log_path.read_text(encoding="utf-8", errors="ignore"), max_chars)
        return {"meta": meta, "log": log_text}

    def cancel_job(self, job_id: str) -> dict[str, Any]:
        meta = self._read_meta(job_id)
        pid = meta.get("pid")
        if not pid:
            return {"job_id": job_id, "cancelled": False}
        previous_status = str(meta.get("status") or "running")
        meta["status"] = "cancelling"
        self._write_meta(job_id, meta)
        cancelled = False
        if meta.get("job_type") == "project_launch" and os.name != "nt":
            with suppress(Exception):
                os.killpg(int(pid), 15)
                cancelled = True
        elif meta.get("job_type") == "project_launch" and shutil.which("taskkill.exe") is not None:
            with suppress(Exception):
                completed = subprocess.run(
                    ["taskkill.exe", "/PID", str(pid), "/T", "/F"],
                    capture_output=True,
                    text=True,
                    timeout=30,
                    check=False,
                )
                cancelled = completed.returncode == 0
        else:
            with suppress(Exception):
                os.kill(int(pid), 15)
                cancelled = True
        if not cancelled:
            meta["status"] = previous_status
            self._write_meta(job_id, meta)
            return {"job_id": job_id, "cancelled": False}
        meta["status"] = "cancelled"
        meta["finished_at"] = _now_stamp()
        self._write_meta(job_id, meta)
        return {"job_id": job_id, "cancelled": True}


def _is_windows_backed_workspace(workspace: Path) -> bool:
    resolved = workspace.resolve().as_posix()
    if re.match(r"^[A-Za-z]:[/\\]", resolved):
        return True
    return resolved.startswith("/mnt/") and len(resolved) >= 7 and resolved[5].isalpha() and resolved[6] == "/"


def _path_exists_safely(path: Path) -> bool:
    try:
        return path.exists()
    except OSError:
        return False


def _preferred_project_python(workspace: Path) -> Path | None:
    linux_candidate = _preferred_project_linux_python(workspace)
    windows_candidate = _preferred_project_windows_python(workspace)
    if os.name == "nt":
        candidates = (windows_candidate, linux_candidate)
    else:
        candidates = (linux_candidate, windows_candidate)
    return next((candidate for candidate in candidates if candidate is not None), None)


def _project_environment_candidates(
    workspace: Path,
    environment_root: Path | None = None,
) -> list[tuple[Path, Path, str]]:
    """Return environment-root, interpreter, and layout candidates under the active workspace."""
    if environment_root is not None:
        roots = [environment_root]
    else:
        roots = [
            workspace / ".venv",
            workspace / ".venv312",
            workspace / ".venv313",
            workspace / ".venv_wsl",
            workspace / ".venv_linux",
            workspace / ".venv_win",
            workspace / "venv",
            workspace / "env",
        ]
        try:
            roots.extend(child for child in sorted(workspace.iterdir()) if child.is_dir())
        except OSError:
            pass

    candidates: list[tuple[Path, Path, str]] = []
    seen: set[str] = set()
    for root in roots:
        direct_name = root.name.lower()
        layouts = (
            [(root.parent.parent, root, "windows")]
            if direct_name == "python.exe"
            else [(root.parent.parent, root, "linux")]
            if direct_name in {"python", "python3"}
            else [
                (root, root / "Scripts" / "python.exe", "windows"),
                (root, root / "bin" / "python", "linux"),
            ]
        )
        for candidate_root, interpreter, layout in layouts:
            key = str(interpreter).replace("\\", "/").casefold()
            if key in seen or not _path_exists_safely(interpreter):
                continue
            seen.add(key)
            candidates.append((candidate_root, interpreter, layout))
    return candidates

def _explicit_prompt_environment(prompt: str) -> str | None:
    """Extract only a high-confidence project-environment path explicitly named by the user."""
    text = str(prompt or "")
    assignment = re.search(
        r"\benvironment\s*=\s*([`'\"]?)([^\s,;`'\"]+)\1",
        text,
        re.IGNORECASE,
    )
    if assignment is not None:
        return assignment.group(2).strip()
    matches = re.findall(
        r"(?<![A-Za-z0-9_.-])([A-Za-z0-9_./\\:-]*\.venv[A-Za-z0-9._-]*|"
        r"[A-Za-z0-9_./\\:-]*\bvenv[0-9][A-Za-z0-9._-]*)(?=$|[\s,;:`'\"])",
        text,
        re.IGNORECASE,
    )
    return matches[-1].strip() if matches else None

def _probe_python_environment(
    environment_root: Path,
    python_executable: Path,
    layout: str,
) -> dict[str, Any]:
    """Execute an environment's interpreter and classify the environment from runtime facts."""
    result: dict[str, Any] = {
        "status": "unusable",
        "environment_root": str(environment_root),
        "python": str(python_executable),
        "layout": layout,
        "pyvenv_cfg_present": _path_exists_safely(environment_root / "pyvenv.cfg"),
        "return_code": None,
        "returncode": None,
    }
    if os.name == "nt" and layout == "linux":
        result["reason"] = "A WSL/Linux interpreter cannot be executed directly by the Windows host process."
        return result
    probe_code = (
        "import json,sys;"
        "print(json.dumps({'sys_executable':sys.executable,'sys_prefix':sys.prefix,"
        "'sys_base_prefix':sys.base_prefix,'sys_platform':sys.platform,"
        "'python_version':'.'.join(map(str,sys.version_info[:3]))},sort_keys=True))"
    )
    try:
        completed = subprocess.run(
            [str(python_executable), "-I", "-c", probe_code],
            cwd=environment_root.parent if environment_root.parent.is_dir() else None,
            capture_output=True,
            timeout=20,
            check=False,
        )
    except Exception as exc:
        result["reason"] = f"Interpreter execution failed: {type(exc).__name__}: {exc}"
        return result
    stdout = _decode_subprocess_output(completed.stdout)
    stderr = _decode_subprocess_output(completed.stderr)
    result.update(
        {
            "return_code": completed.returncode,
            "returncode": completed.returncode,
            "stdout": _shorten(stdout, 2000),
            "stderr": _shorten(stderr, 4000),
        }
    )
    if completed.returncode != 0:
        result["reason"] = "The interpreter exists but its direct execution probe failed."
        return result
    payload: dict[str, Any] | None = None
    for line in reversed(stdout.splitlines()):
        with suppress(json.JSONDecodeError):
            decoded = json.loads(line)
            if isinstance(decoded, dict) and decoded.get("sys_executable"):
                payload = decoded
                break
    if payload is None:
        result["reason"] = "The interpreter ran but did not return the required runtime facts."
        return result
    result.update(payload)
    platform_name = str(payload.get("sys_platform") or "").lower()
    host_in_wsl = False
    with suppress(OSError):
        host_in_wsl = any(
            token in Path("/proc/version").read_text(encoding="utf-8", errors="ignore").lower()
            for token in ("microsoft", "wsl")
        )
    actual_kind = "windows" if platform_name == "win32" else "wsl_linux" if host_in_wsl else "linux"
    result["kind"] = actual_kind
    if (layout == "windows") != (actual_kind == "windows"):
        result["reason"] = f"Interpreter platform {platform_name or 'unknown'} does not match its {layout} layout."
        return result
    prefix = str(payload.get("sys_prefix") or "").replace("\\", "/").rstrip("/").casefold()
    base_prefix = str(payload.get("sys_base_prefix") or "").replace("\\", "/").rstrip("/").casefold()
    if not prefix or prefix == base_prefix:
        result["reason"] = "The interpreter ran, but sys.prefix does not identify an isolated virtual environment."
        return result
    result["status"] = "ready"
    result["reason"] = "The exact environment interpreter executed successfully and reported an isolated prefix."
    return result

def _inspect_project_python_environment(
    base: Any,
    workspace: Path,
    environment: str | None = None,
) -> dict[str, Any]:
    """Resolve a named environment from the active workspace and validate it by execution."""
    workspace = workspace.resolve()
    requested = str(environment or "").strip()
    environment_root: Path | None = None
    if requested:
        environment_root = base.resolve_workspace_path(
            workspace,
            requested,
            allow_missing=True,
            allow_external=True,
        )
    candidates = _project_environment_candidates(workspace, environment_root)
    probes = [
        _probe_python_environment(candidate_root, interpreter, layout)
        for candidate_root, interpreter, layout in candidates
    ]
    ready = [probe for probe in probes if probe.get("status") == "ready"]

    def display_path(value: str) -> str:
        path = Path(value)
        with suppress(ValueError):
            return str(path.resolve().relative_to(workspace)).replace("\\", "/") or "."
        return str(path)

    for probe in probes:
        probe["environment"] = display_path(str(probe["environment_root"]))
        probe["python"] = str(probe["python"])
    common = {
        "workspace": str(workspace),
        "requested_environment": requested or None,
        "candidates": probes,
    }
    if len(ready) == 1:
        selected = dict(ready[0])
        selected.pop("environment_root", None)
        return {**common, **selected}
    if len(ready) > 1:
        return {
            **common,
            "status": "ambiguous",
            "reason": (
                "Multiple executable project-local Python environments were found; pass environment explicitly."
            ),
        }
    if probes:
        return {
            **common,
            "status": "unusable",
            "reason": "Environment candidates were found, but every exact interpreter execution probe failed.",
        }
    expected_root = environment_root if environment_root is not None else workspace
    return {
        **common,
        "status": "not_found",
        "reason": (
            f"No Scripts/python.exe or bin/python interpreter was found under {display_path(str(expected_root))}."
        ),
    }

def _preferred_project_linux_python(workspace: Path) -> Path | None:
    for environment_root, candidate, layout in _project_environment_candidates(workspace):
        if layout == "linux" and _probe_python_environment(environment_root, candidate, layout).get("status") == "ready":
            return candidate
    return None


def _preferred_project_windows_python(workspace: Path) -> Path | None:
    for environment_root, candidate, layout in _project_environment_candidates(workspace):
        if layout == "windows" and _probe_python_environment(environment_root, candidate, layout).get("status") == "ready":
            return candidate
    return None


def _select_direct_workspace_python(base: Any, workspace: Path) -> tuple[Path, str] | None:
    capabilities = _workspace_runtime_capabilities(base, workspace)
    interpreter = capabilities.get("preferred_python_path")
    runner = capabilities.get("preferred_python_runner")
    if isinstance(interpreter, Path) and interpreter.exists() and runner in {"shell", "powershell"}:
        environment_root = interpreter.parent.parent
        layout = "windows" if interpreter.suffix.lower() == ".exe" else "linux"
        probe = _probe_python_environment(environment_root, interpreter, layout)
        if probe.get("status") == "ready":
            return interpreter, str(runner)
    return None


def _repo_local_wsl_llamacpp_process_ids() -> list[int]:
    if os.name == "nt":
        return []
    repo_root = str(Path.cwd().resolve()).replace("\\", "/")
    completed = subprocess.run(
        ["ps", "-eo", "pid=,args="],
        capture_output=True,
        text=True,
        timeout=30,
        check=False,
    )
    process_ids: set[int] = set()
    for raw_line in (completed.stdout or "").splitlines():
        line = raw_line.strip()
        if not line or "llama-server" not in line or repo_root not in line:
            continue
        pid_text, _, _ = line.partition(" ")
        try:
            process_ids.add(int(pid_text))
        except ValueError:
            continue
    return sorted(process_ids)


def _terminate_repo_local_wsl_llamacpp_processes(excluded: set[int] | None = None) -> list[int]:
    if os.name == "nt":
        return []
    excluded_ids = excluded or set()
    terminated: list[int] = []
    for pid in _repo_local_wsl_llamacpp_process_ids():
        if pid in excluded_ids:
            continue
        try:
            os.kill(pid, 15)
            terminated.append(pid)
        except OSError:
            continue
    if not terminated:
        return []
    deadline = time.time() + 2.0
    remaining = list(terminated)
    while remaining and time.time() < deadline:
        still_running: list[int] = []
        for pid in remaining:
            try:
                os.kill(pid, 0)
            except OSError:
                continue
            still_running.append(pid)
        if not still_running:
            return sorted(terminated)
        remaining = still_running
        time.sleep(0.2)
    for pid in remaining:
        try:
            os.kill(pid, 9)
        except OSError:
            continue
    return sorted(terminated)


def _enable_local_only_environment() -> None:
    os.environ.setdefault("QUBITZ_ALLOW_EMBED_ONLINE", "1")


def _powershell_single_quote(value: str) -> str:
    return "'" + value.replace("'", "''") + "'"


def _workspace_windows_path(base: Any, workspace: Path) -> str:
    translator = getattr(base, "wsl_path_to_windows", None)
    if callable(translator):
        translated = translator(workspace)
        if translated:
            return str(translated)
    fallback = getattr(base, "wsl_path_to_windows_path", None)
    if callable(fallback):
        return str(fallback(workspace))
    return str(workspace)


def _extract_powershell_script(command: str) -> str:
    stripped = command.strip()
    lower = stripped.lower()
    for prefix in ("powershell.exe", "powershell", "pwsh.exe", "pwsh"):
        token = prefix + " "
        if lower.startswith(token):
            script = stripped[len(token) :].lstrip()
            while True:
                lowered_script = script.lower()
                if lowered_script.startswith("-noprofile "):
                    script = script[len("-noprofile ") :].lstrip()
                    continue
                if lowered_script.startswith("-command "):
                    script = script[len("-command ") :].lstrip()
                    continue
                if lowered_script.startswith("-c "):
                    script = script[len("-c ") :].lstrip()
                    continue
                break
            if len(script) >= 2 and script[0] == script[-1] and script[0] in {"'", '"'}:
                script = script[1:-1]
            return script
    return stripped


def _shell_quote_path(path: Path | str) -> str:
    text = str(path)
    if os.name == "nt":
        return f'"{text}"'
    return shlex.quote(text)


def _canonicalize_workspace_command(workspace: Path, command: str) -> str:
    normalized = command.strip()
    shell_match = re.match(
        r"^\s*(?P<shell>(?:bash|sh)(?:\.exe)?)\s+(?P<flag>-lc|-c)\s+(?P<script>.+)$",
        normalized,
        flags=re.IGNORECASE,
    )
    if shell_match:
        script = shell_match.group("script").strip()
        if len(script) >= 2 and script[0] == script[-1] and script[0] in {"'", '"'}:
            script = script[1:-1]
        rewritten = _canonicalize_workspace_command(workspace, script)
        return f"{shell_match.group('shell')} {shell_match.group('flag')} {shlex.quote(rewritten)}"
    python_match = re.match(r"^\s*(?P<launcher>python(?:\.exe)?|python3|py)\s+(?P<rest>.+)$", normalized, flags=re.IGNORECASE)
    if not python_match:
        return command
    interpreter = _preferred_project_python(workspace)
    if interpreter is None:
        return command
    rest = python_match.group("rest").strip()
    return f"{_shell_quote_path(interpreter)} {rest}".rstrip()


def _canonicalize_workspace_script(base: Any, workspace: Path, script: str) -> str:
    normalized = script.strip()
    activation_match = re.match(
        r"^\s*(?P<activate>\.[\\/][^;]*?[\\/](?:Scripts[\\/ ]Activate\.ps1|bin[\\/]activate))\s*;\s*(?P<rest>.+)$",
        normalized,
        flags=re.IGNORECASE,
    )
    if activation_match:
        activate_path = activation_match.group("activate")
        if "\\" in activate_path and not re.match(r"^[A-Za-z]:[\\/]", activate_path):
            activate_path = activate_path.replace("\\", "/")
        rest = activation_match.group("rest").strip()
        python_launcher_match = re.match(
            r"^(?:python(?:\.exe)?|py|(?:\.[\\/][^\s]*?(?:Scripts[\\/]python\.exe|bin[\\/]python)))\s+(?P<rest>.+)$",
            rest,
            flags=re.IGNORECASE,
        )
        if python_launcher_match:
            rest = python_launcher_match.group("rest").strip()
        activate_candidate = (workspace / activate_path).resolve()
        if activate_candidate.name.lower() == "activate.ps1":
            interpreter = activate_candidate.parent / "python.exe"
            if interpreter.exists():
                translated = _workspace_windows_path(base, interpreter)
                return f"& {_powershell_single_quote(translated)} {rest}"
        if activate_candidate.name.lower() == "activate":
            interpreter = activate_candidate.parent / "python"
            if interpreter.exists():
                return f"& {_powershell_single_quote(str(interpreter))} {rest}"
    python_launcher_match = re.match(
        r"^\s*(?P<launcher>python(?:\.exe)?|python3|py)\s+(?P<rest>.+)$",
        normalized,
        flags=re.IGNORECASE,
    )
    if python_launcher_match:
        interpreter = _preferred_project_python(workspace)
        if interpreter is not None:
            rest = python_launcher_match.group("rest").strip()
            if interpreter.suffix.lower() == ".exe":
                translated = _workspace_windows_path(base, interpreter)
                return f"& {_powershell_single_quote(translated)} {rest}"
            return f"& {_powershell_single_quote(str(interpreter))} {rest}"
    python_match = re.match(
        r"^\s*(?P<python>\.[\\/][^;]*?[\\/]Scripts[\\/]python\.exe)\s*(?P<rest>.*)$",
        normalized,
        flags=re.IGNORECASE,
    )
    if python_match:
        python_text = python_match.group("python")
        if "\\" in python_text and not re.match(r"^[A-Za-z]:[\\/]", python_text):
            python_text = python_text.replace("\\", "/")
        interpreter = (workspace / python_text).resolve()
        if interpreter.exists():
            translated = _workspace_windows_path(base, interpreter)
            rest = python_match.group("rest").strip()
            return f"& {_powershell_single_quote(translated)} {rest}".rstrip()
    return script


def _should_use_windows_shell(base: Any, workspace: Path, command: str) -> bool:
    if not callable(getattr(base, "in_wsl", None)) or not base.in_wsl():
        return False
    if shutil.which("powershell.exe") is None:
        return False
    stripped = command.strip()
    if not stripped:
        return False
    lower = stripped.lower()
    first_token = stripped.split(maxsplit=1)[0].strip("'\"")
    first_token_posix = first_token.replace("\\", "/")
    if re.match(r"^\./[^;&|]*?/bin/python(?:3(?:\.\d+)?)?$", first_token_posix, flags=re.IGNORECASE):
        candidate = (workspace / first_token_posix).resolve()
        if candidate.is_file() and candidate.suffix.lower() != ".exe":
            return False
    if lower.startswith(("powershell ", "powershell.exe ", "pwsh ", "pwsh.exe ")):
        return True
    if any(token in lower for token in (".ps1", ".bat", ".cmd")):
        return True
    if _is_windows_backed_workspace(workspace) and re.search(r"(^|[\s;&|])\.[\\/]", stripped):
        return True
    pattern = getattr(base, "WINDOWS_DRIVE_PATH_PATTERN", None)
    if pattern is not None and pattern.match(stripped):
        return True
    if "\\" in first_token and first_token.lower().endswith((".exe", ".cmd", ".bat")):
        return True
    return False


class _CommandResult(dict[str, Any]):
    __slots__ = ("stdout_full", "stderr_full")

    def __init__(self, payload: dict[str, Any], *, stdout_full: str, stderr_full: str) -> None:
        super().__init__(payload)
        self.stdout_full = stdout_full
        self.stderr_full = stderr_full


def _terminate_windows_process_token(token: str) -> None:
    powershell = shutil.which("pwsh.exe") or shutil.which("powershell.exe")
    if powershell is None or not token:
        return
    escaped = token.replace("'", "''")
    script = (
        f"$needle = '{escaped}'; "
        "$matches = Get-CimInstance Win32_Process | Where-Object { "
        "$_.ProcessId -ne $PID -and $_.CommandLine -and "
        "$_.CommandLine.IndexOf($needle, [StringComparison]::Ordinal) -ge 0 }; "
        "$matches | ForEach-Object { & taskkill.exe /PID $_.ProcessId /T /F 2>$null | Out-Null }"
    )
    command = [powershell, "-NoProfile", "-Command", script]
    if os.name != "nt" and Path("/init").is_file() and powershell.lower().endswith(".exe"):
        command.insert(0, "/init")
    with suppress(Exception):
        subprocess.run(command, capture_output=True, timeout=15, check=False)


def _terminate_owned_process(process: subprocess.Popen[bytes], windows_token: str = "") -> None:
    if windows_token:
        _terminate_windows_process_token(windows_token)
    if process.poll() is not None:
        return
    with suppress(Exception):
        if os.name == "nt":
            subprocess.run(
                ["taskkill.exe", "/PID", str(process.pid), "/T", "/F"],
                capture_output=True,
                timeout=15,
                check=False,
            )
        else:
            os.killpg(os.getpgid(process.pid), 15)
    with suppress(Exception):
        process.wait(timeout=3)
    if process.poll() is None:
        with suppress(Exception):
            process.kill()


def _run_owned_process(
    command: Sequence[str] | str,
    *,
    cwd: Path,
    timeout_seconds: int,
    cancel_event: threading.Event | None = None,
    shell: bool = False,
    windows_token: str = "",
) -> tuple[int, bytes, bytes]:
    popen_kwargs: dict[str, Any] = {
        "cwd": cwd,
        "stdout": subprocess.PIPE,
        "stderr": subprocess.PIPE,
        "shell": shell,
    }
    if os.name == "nt":
        popen_kwargs["creationflags"] = getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
    else:
        popen_kwargs["start_new_session"] = True
    process = subprocess.Popen(command, **popen_kwargs)
    deadline = time.monotonic() + max(1, timeout_seconds)
    while True:
        try:
            stdout, stderr = process.communicate(timeout=0.2)
            return int(process.returncode or 0), stdout or b"", stderr or b""
        except subprocess.TimeoutExpired:
            if cancel_event is not None and cancel_event.is_set():
                _terminate_owned_process(process, windows_token)
                with suppress(Exception):
                    process.communicate(timeout=2)
                raise InterruptedError("Command cancelled by the active Qubitz request.")
            if time.monotonic() >= deadline:
                _terminate_owned_process(process, windows_token)
                raise subprocess.TimeoutExpired(command, timeout_seconds)


def _run_shell_command(
    base: Any,
    workspace: Path,
    command: str,
    timeout_seconds: int,
    cancel_event: threading.Event | None = None,
) -> dict[str, Any]:
    if _should_use_windows_shell(base, workspace, command):
        result = _run_powershell_command(base, workspace, command, timeout_seconds, cancel_event=cancel_event)
        result["returncode"] = int(result.get("return_code", 0))
        return result
    else:
        command = _canonicalize_workspace_command(workspace, command)
        return_code, stdout_data, stderr_data = _run_owned_process(
            command,
            cwd=workspace,
            timeout_seconds=timeout_seconds,
            cancel_event=cancel_event,
            shell=True,
        )
    stdout_full = _decode_subprocess_output(stdout_data)
    stderr_full = _decode_subprocess_output(stderr_data)
    result = _CommandResult(
        {
            "command": command,
            "returncode": return_code,
            "stdout": _shorten(stdout_full, 12000),
            "stderr": _shorten(stderr_full, 12000),
        },
        stdout_full=stdout_full,
        stderr_full=stderr_full,
    )
    return result


def _run_powershell_command(
    base: Any,
    workspace: Path,
    command: str,
    timeout_seconds: int,
    cancel_event: threading.Event | None = None,
) -> dict[str, Any]:
    powershell = shutil.which("powershell.exe") or shutil.which("pwsh.exe") or shutil.which("pwsh")
    if powershell is None:
        raise RuntimeError("PowerShell was not found on this system.")
    use_windows_paths = powershell.lower().endswith(".exe") and callable(getattr(base, "in_wsl", None)) and base.in_wsl()
    launch_command = [powershell]
    if use_windows_paths and Path("/init").is_file():
        launch_command.insert(0, "/init")
    workspace_windows = _workspace_windows_path(base, workspace) if use_windows_paths else str(workspace)
    script_body = _canonicalize_workspace_script(base, workspace, _extract_powershell_script(command))
    windows_token = f"QUBITZ_TASK_{uuid.uuid4().hex}"
    script_lines = [
        f"$null = '{windows_token}'",
        "$ProgressPreference = 'SilentlyContinue'",
        f"Set-Location -LiteralPath {_powershell_single_quote(workspace_windows)}",
        script_body,
    ]
    return_code, stdout_data, stderr_data = _run_owned_process(
        [*launch_command, "-NoProfile", "-Command", "; ".join(line for line in script_lines if line)],
        cwd=workspace,
        timeout_seconds=timeout_seconds,
        cancel_event=cancel_event,
        windows_token=windows_token if use_windows_paths or os.name == "nt" else "",
    )
    stdout_full = _decode_subprocess_output(stdout_data)
    stderr_full = _decode_subprocess_output(stderr_data)
    result = _CommandResult(
        {
            "command": command,
            "return_code": return_code,
            "stdout": _shorten(stdout_full, 12000),
            "stderr": _shorten(stderr_full, 12000),
        },
        stdout_full=stdout_full,
        stderr_full=stderr_full,
    )
    return result


def _decode_text_preserving_encoding(
    data: bytes,
    path_label: str,
) -> tuple[str, str, bytes]:
    bom_encodings = (
        (b"\xff\xfe\x00\x00", "utf-32-le", "utf-32-le-bom"),
        (b"\x00\x00\xfe\xff", "utf-32-be", "utf-32-be-bom"),
        (b"\xef\xbb\xbf", "utf-8", "utf-8-bom"),
        (b"\xff\xfe", "utf-16-le", "utf-16-le-bom"),
        (b"\xfe\xff", "utf-16-be", "utf-16-be-bom"),
    )
    for bom, codec, label in bom_encodings:
        if data.startswith(bom):
            return data[len(bom) :].decode(codec), label, bom
    try:
        return data.decode("utf-8"), "utf-8", b""
    except UnicodeDecodeError as exc:
        raise ValueError(
            f"{path_label} is neither UTF-8 nor BOM-marked UTF-16/UTF-32 text. "
            "Its encoding is ambiguous; provide an explicit encoding or use a format-aware tool."
        ) from exc

def _encode_text_preserving_encoding(text: str, encoding_label: str, bom: bytes) -> bytes:
    codec_by_label = {
        "utf-8": "utf-8",
        "utf-8-bom": "utf-8",
        "utf-16-le-bom": "utf-16-le",
        "utf-16-be-bom": "utf-16-be",
        "utf-32-le-bom": "utf-32-le",
        "utf-32-be-bom": "utf-32-be",
    }
    codec = codec_by_label.get(encoding_label)
    if codec is None:
        raise ValueError(f"Unsupported preserved text encoding: {encoding_label}")
    return bom + text.encode(codec)

def _extract_explicit_quoted_edit_target(prompt: str) -> str:
    """Return a high-confidence user-supplied current text span for an edit."""
    if not prompt.strip():
        return ""
    quoted_matches: list[tuple[int, str]] = []
    for pattern in (r'"([^"\r\n]{8,12000})"', r"\u201c([^\u201d\r\n]{8,12000})\u201d"):
        quoted_matches.extend(
            (match.start(), match.group(1).strip())
            for match in re.finditer(pattern, prompt, re.DOTALL)
        )
    for start, candidate in sorted(quoted_matches, key=lambda item: item[0]):
        prefix = prompt[max(0, start - 360) : start]
        if not re.search(
            r"\b(?:edit|update|modify|change|replace|rewrite)\b",
            prefix,
            re.IGNORECASE,
        ):
            continue
        if re.search(r"\b(?:to|with|as)\s*:?[\s,]*$", prefix, re.IGNORECASE):
            continue
        if not re.search(
            r"\b(?:this|current|existing|old|original|the\s+(?:current|existing|old|original))\s+"
            r"(?:part|text|passage|paragraph|section|content)\b"
            r"(?:\s+(?:inside|in)\s+(?:it|the\s+(?:file|document)))?\s*:?[\s,]*$",
            prefix,
            re.IGNORECASE | re.DOTALL,
        ):
            continue
        return candidate
    return ""

def _binary_file_notice(path: Path) -> str:
    """Return guidance when a file cannot be usefully read or searched as text."""
    document_handlers = {
        ".doc": "Microsoft Word or LibreOffice automation",
        ".docx": "python-docx",
        ".xlsx": "openpyxl",
        ".xlsm": "openpyxl",
        ".pptx": "python-pptx",
        ".pdf": "a PDF-aware editor or source-document regeneration workflow",
        ".odt": "odfpy",
        ".ods": "odfpy",
        ".odp": "odfpy",
    }
    opaque_extensions = {
        ".7z", ".bin", ".bmp", ".dll", ".exe", ".gguf", ".gif", ".gz", ".ico",
        ".jpeg", ".jpg", ".mp3", ".mp4", ".npy", ".npz", ".pack", ".png",
        ".pt", ".pth", ".pyc", ".pyd", ".rar", ".so", ".sqlite", ".tar",
        ".wav", ".webp", ".whl", ".woff", ".woff2", ".zip",
    }
    suffix = path.suffix.lower()
    if suffix in document_handlers:
        handler = document_handlers[suffix]
        if suffix == ".docx":
            return (
                f"{path.name} is a .docx document; its raw bytes are not text. "
                "read_file_snapshot returns a bounded read-only paragraph preview and binds the current SHA-256; "
                "use that readable preview as document context, then use "
                "apply_docx_text_patch for exact transactional replacements. "
                f"That tool uses {handler} from the active workspace's project-local Python environment, "
                "preserves paragraph/list properties and existing character formatting, and leaves the original "
                "unchanged if loading, replacement, verification, or commit fails. Do not claim the DOCX content "
                "is unreadable merely because its container is binary."
            )
        return (
            f"{path.name} is a {suffix} document; its raw bytes are not text. "
            f"Use a dedicated format-aware tool backed by {handler}; raw text patch tools are not valid "
            "for this format. Preserve its layout, styles, metadata, and unaffected content. Do not silently "
            "flatten, convert, or rewrite it when faithful editing is unavailable."
        )
    if suffix in opaque_extensions:
        return f"{path.name} is a binary {suffix} file and has no readable text content."
    try:
        with path.open("rb") as handle:
            prefix = handle.read(4096)
            text_boms = (
                b"\xff\xfe\x00\x00",
                b"\x00\x00\xfe\xff",
                b"\xef\xbb\xbf",
                b"\xff\xfe",
                b"\xfe\xff",
            )
            if any(prefix.startswith(bom) for bom in text_boms):
                return ""
            if b"\x00" in prefix:
                return f"{path.name} appears to be a binary file and has no readable text content."
    except OSError:
        pass
    return ""


def _build_local_mcp_server(base: Any, workspace: Path, runtime_workspace: Path, launch_script: Path) -> Any:
    workspace = workspace.resolve()
    runtime_workspace = runtime_workspace.resolve()
    local_config = LocalOnlyConfig.load(runtime_workspace, workspace)
    plugins_enabled = local_config.plugins_enabled and _local_plugins_available(runtime_workspace, workspace)
    skills_enabled = _local_skills_available(runtime_workspace)
    sandbox_tools_enabled = _sandbox_features_enabled(local_config)
    background_jobs_enabled = local_config.background_jobs_enabled
    plugin_registry: Any = (
        LocalPluginRegistry(runtime_workspace, workspace) if plugins_enabled else _DisabledLocalPluginRegistry()
    )
    skills = base.SkillRegistry(runtime_workspace) if skills_enabled else None
    sandboxes: Any = (
        LocalSandboxManager(workspace, runtime_workspace, getattr(base, "EXCLUDED_DIRS", set()), base=base)
        if sandbox_tools_enabled
        else _DisabledLocalSandboxManager()
    )
    jobs: Any = (
        LocalBackgroundJobManager(runtime_workspace, launch_script)
        if background_jobs_enabled
        else _DisabledLocalBackgroundJobManager()
    )
    mcp_servers = LocalMCPServerManager(workspace, runtime_workspace, base=base)
    server = base.FastMCP(
        "Qubitz Local-Only Tools",
        json_response=True,
        instructions="Local-only filesystem, code intelligence, sandbox, plugin, and background-job tools.",
    )
    memory_dir = runtime_workspace / ".memory"
    memory_dir.mkdir(parents=True, exist_ok=True)
    current_memory_path = memory_dir / getattr(base, "CURRENT_MEMORY_NAME", "MEMORY.md")
    codeintel = LocalCodeIntel(
        workspace,
        runtime_workspace,
        excluded_dirs=getattr(base, "EXCLUDED_DIRS", set()),
        text_suffixes=getattr(base, "TEXT_SUFFIXES", {".py", ".md", ".txt"}),
        max_files=local_config.codeintel_max_files,
    )

    def _resolve(candidate: str, *, allow_missing: bool = True, allow_external: bool = False) -> Path:
        return base.resolve_workspace_path(
            workspace,
            candidate,
            allow_missing=allow_missing,
            allow_external=allow_external,
        )

    def _read_text(candidate: Path) -> str:
        return candidate.read_text(encoding="utf-8", errors="ignore")

    def _relative_exclusion_parts(candidate: Path, requested_root: Path) -> tuple[str, ...]:
        for anchor in (workspace, requested_root):
            with suppress(ValueError):
                return candidate.relative_to(anchor).parts
        return (candidate.name,)

    def _is_excluded_candidate(candidate: Path, requested_root: Path) -> bool:
        excluded = {str(part).casefold() for part in getattr(base, "EXCLUDED_DIRS", set())}
        return any(
            part.casefold() in excluded
            for part in _relative_exclusion_parts(candidate, requested_root)
        )

    @server.resource("workspace://summary")
    def workspace_summary() -> str:
        return json.dumps(
            {
                "workspace": workspace.as_posix(),
                "runtime_workspace": runtime_workspace.as_posix(),
                "memory_file": base.relative_path(current_memory_path, runtime_workspace),
                "skills_root": base.relative_path(_local_skills_root(runtime_workspace), runtime_workspace),
                "skill_count": skills.count() if skills is not None else 0,
                "skill_warnings": skills.warnings if skills is not None else [],
                "local_only_config": local_config.__dict__,
                "plugin_count": len(plugin_registry.plugins),
            },
            ensure_ascii=True,
            indent=2,
        )

    @server.resource("memory://current")
    def memory_resource() -> str:
        if not current_memory_path.exists():
            return ""
        return current_memory_path.read_text(encoding="utf-8", errors="ignore")

    if skills is not None:
        @server.resource("skills://index")
        def skills_index() -> str:
            return json.dumps(
                {
                    "skills_root": base.relative_path(skills.skills_root, runtime_workspace),
                    "count": skills.count(),
                    "warnings": skills.warnings,
                    "skills": skills.list_summaries(),
                },
                ensure_ascii=True,
                indent=2,
            )

    if plugins_enabled:
        @server.resource("plugins://index")
        def plugins_index() -> str:
            return json.dumps({"plugins": plugin_registry.list_plugins()}, ensure_ascii=True, indent=2)

    @server.tool(description="List files or directories inside the active workspace.")
    def list_files(path: str = ".", recursive: bool = False, max_entries: int = 200) -> dict[str, Any]:
        root = _resolve(path, allow_missing=False, allow_external=True)
        iterator = root.rglob("*") if recursive else root.iterdir()
        entries: list[dict[str, Any]] = []
        for candidate in sorted(iterator):
            if candidate != root and _is_excluded_candidate(candidate, root):
                continue
            entries.append(
                {
                    "path": base.relative_path(candidate, workspace),
                    "is_dir": candidate.is_dir(),
                    "size": candidate.stat().st_size if candidate.is_file() else None,
                }
            )
            if len(entries) >= max_entries:
                break
        return {"root": base.relative_path(root, workspace), "entries": entries}

    @server.tool(description="Read a text file from the active workspace or an explicit absolute path.")
    def read_file(path: str, start_line: int = 1, end_line: int = 200) -> dict[str, Any]:
        target = _resolve(path, allow_missing=False, allow_external=True)
        if not target.is_file():
            raise ValueError(f"Not a file: {path}")
        binary_notice = _binary_file_notice(target)
        if binary_notice:
            return {
                "path": base.relative_path(target, workspace),
                "start_line": 0,
                "end_line": 0,
                "content": "",
                "binary": True,
                "notice": binary_notice,
            }
        lines = _read_text(target).splitlines()
        start_index = max(start_line - 1, 0)
        end_index = min(end_line, len(lines))
        excerpt = "\n".join(lines[start_index:end_index])
        return {
            "path": base.relative_path(target, workspace),
            "start_line": start_index + 1,
            "end_line": end_index,
            "content": excerpt,
        }

    @server.tool(description="Write or overwrite a file inside the active workspace.")
    def write_file(path: str, content: str, make_parents: bool = True) -> dict[str, Any]:
        target = _resolve(path, allow_external=True)
        if make_parents:
            target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        return {"path": base.relative_path(target, workspace), "bytes_written": target.stat().st_size}

    @server.tool(description="Replace exact text inside a file in the active workspace.")
    def replace_text(path: str, old_text: str, new_text: str, count: int = 0) -> dict[str, Any]:
        target = _resolve(path, allow_missing=False, allow_external=True)
        original = _read_text(target)
        replacements = original.count(old_text) if count == 0 else min(original.count(old_text), count)
        updated = original.replace(old_text, new_text, count) if count > 0 else original.replace(old_text, new_text)
        if updated != original:
            target.write_text(updated, encoding="utf-8")
        return {"path": base.relative_path(target, workspace), "replacements": replacements}

    @server.tool(description="Delete a file or directory inside the active workspace.")
    def delete_path(path: str, recursive: bool = False) -> dict[str, Any]:
        target = _resolve(path, allow_missing=False, allow_external=True)
        if target.is_dir():
            if recursive:
                shutil.rmtree(target)
            else:
                target.rmdir()
        else:
            target.unlink()
        return {"deleted": base.relative_path(target, workspace), "recursive": recursive}

    @server.tool(description="Create a directory inside the active workspace.")
    def make_directory(path: str) -> dict[str, Any]:
        target = _resolve(path, allow_external=True)
        target.mkdir(parents=True, exist_ok=True)
        return {"path": base.relative_path(target, workspace), "created": True}

    @server.tool(description="Move or rename a path inside the active workspace.")
    def move_path(source: str, destination: str, overwrite: bool = False) -> dict[str, Any]:
        source_path = _resolve(source, allow_missing=False, allow_external=True)
        destination_path = _resolve(destination, allow_external=True)
        destination_path.parent.mkdir(parents=True, exist_ok=True)
        if destination_path.exists():
            if not overwrite:
                raise ValueError(f"Destination already exists: {destination}")
            if destination_path.is_dir():
                shutil.rmtree(destination_path)
            else:
                destination_path.unlink()
        shutil.move(str(source_path), str(destination_path))
        return {
            "source": base.relative_path(source_path, workspace),
            "destination": base.relative_path(destination_path, workspace),
        }

    @server.tool(description="Search text content inside active workspace files.")
    def search_text(
        query: str,
        path: str = ".",
        file_glob: str = "*",
        max_results: int = 50,
        case_sensitive: bool = False,
    ) -> dict[str, Any]:
        root = _resolve(path, allow_missing=False, allow_external=True)
        hits: list[dict[str, Any]] = []
        skipped_notices: dict[str, str] = {}
        needle = query if case_sensitive else query.lower()
        for candidate in sorted(root.rglob("*")):
            if not candidate.is_file():
                continue
            if _is_excluded_candidate(candidate, root):
                continue
            if not candidate.match(file_glob) and not Path(base.relative_path(candidate, workspace)).match(file_glob):
                continue
            binary_notice = _binary_file_notice(candidate)
            if binary_notice:
                if len(skipped_notices) < 8:
                    skipped_notices[base.relative_path(candidate, workspace)] = binary_notice
                continue
            text = candidate.read_text(encoding="utf-8", errors="ignore")
            for line_number, line in enumerate(text.splitlines(), start=1):
                haystack = line if case_sensitive else line.lower()
                if needle in haystack:
                    hits.append(
                        {
                            "path": base.relative_path(candidate, workspace),
                            "line": line_number,
                            "content": line.strip(),
                        }
                    )
                    if len(hits) >= max_results:
                        return {"query": query, "matches": hits}
        result: dict[str, Any] = {"query": query, "matches": hits}
        if skipped_notices:
            result["skipped_binary_files"] = sorted(skipped_notices)
            if not hits:
                result["notice"] = next(iter(skipped_notices.values()))
        return result

    @server.tool(
        description=(
            "Run a one-shot local shell command inside the active workspace. "
            "Do not use it to keep a session-scoped stdio MCP script running; use the dedicated MCP tools."
        )
    )
    def run_command(command: str, timeout_seconds: int = 120) -> dict[str, Any]:
        return _run_shell_command(base, workspace, command, timeout_seconds)

    @server.tool(
        description=(
            "Run a bounded PowerShell command inside the active workspace. "
            "Prefer this for Windows-backed workspaces, Activate.ps1, and other PowerShell-specific tasks."
        )
    )
    def run_powershell_command(command: str, cwd: str = ".", timeout_seconds: int = 120) -> dict[str, Any]:
        target_cwd = _resolve(cwd, allow_missing=False, allow_external=True)
        result = _run_powershell_command(base, target_cwd, command, timeout_seconds)
        result["cwd"] = base.relative_path(target_cwd, workspace)
        return result

    @server.tool(
        description=(
            "Resolve a Python environment relative to the active workspace and validate its exact interpreter "
            "by execution. Accepts environment='.venv', environment='.venv312', an explicit environment path, "
            "or no value to discover project-local environments."
        )
    )
    def inspect_python_environment(environment: str | None = None) -> dict[str, Any]:
        return _inspect_project_python_environment(base, workspace, environment)

    @server.tool(
        description=(
            "Install Python packages into an executable active-workspace project-local virtual environment. "
            "Pass environment='.venv' or environment='.venv312' when the user names it; relative values resolve "
            "from the active workspace root. Entries are installed separately with --no-deps, verified through "
            "the target interpreter, and pip fallback requires repeated uv failure plus allow_pip_fallback=true."
        )
    )
    def install_python_package(
        packages: list[str] | None = None,
        requirements_file: str | None = None,
        environment: str | None = None,
        upgrade: bool = False,
        pip_args: list[str] | None = None,
        allow_pip_fallback: bool = False,
    ) -> dict[str, Any]:
        if not packages and not requirements_file:
            raise ValueError("Provide packages and/or requirements_file.")
        inspection = _inspect_project_python_environment(base, workspace, environment)
        if inspection.get("status") != "ready":
            return {
                **inspection,
                "return_code": 2,
                "returncode": 2,
                "commands": [],
                "results": [],
            }
        python_executable = Path(str(inspection["python"]))
        target_kind = str(inspection.get("kind") or "")
        target_is_windows = target_kind == "windows"
        target_native_python = str(inspection.get("sys_executable") or python_executable)

        def runtime_path(path: Path) -> str:
            if target_is_windows:
                return _workspace_windows_path(base, path)
            return str(path)

        commands: list[list[str]] = []
        results: list[dict[str, Any]] = []

        def run_process(
            command: list[str],
            installer: str,
            attempt: int,
            recovery: str = "",
            timeout_seconds: int = 1800,
        ) -> dict[str, Any]:
            commands.append(list(command))
            try:
                completed = subprocess.run(
                    command,
                    cwd=workspace,
                    capture_output=True,
                    timeout=timeout_seconds,
                    check=False,
                )
                return_code = completed.returncode
                stdout = _decode_subprocess_output(completed.stdout)
                stderr = _decode_subprocess_output(completed.stderr)
            except subprocess.TimeoutExpired as exc:
                return_code = 124
                stdout = _decode_subprocess_output(exc.stdout)
                stderr = f"Installer timed out after {timeout_seconds} seconds.\n{_decode_subprocess_output(exc.stderr)}"
            except OSError as exc:
                return_code = 127
                stdout = ""
                stderr = f"{type(exc).__name__}: {exc}"
            entry = {
                "installer": installer,
                "attempt": attempt,
                "recovery": recovery or None,
                "command": list(command),
                "return_code": return_code,
                "returncode": return_code,
                "stdout": _shorten(stdout, 12000),
                "stderr": _shorten(stderr, 12000),
            }
            results.append(entry)
            return entry

        def failure_class(result: dict[str, Any]) -> str:
            output = f"{result.get('stdout', '')}\n{result.get('stderr', '')}".lower()
            if any(
                token in output
                for token in (
                    "connection reset",
                    "connection timed out",
                    "network is unreachable",
                    "read timed out",
                    "remote end closed",
                    "temporary failure",
                    "temporarily unavailable",
                    "too many requests",
                    "timed out",
                    "tls handshake",
                )
            ) or re.search(r"\b(?:429|502|503|504)\b", output):
                return "transient_network"
            if any(
                token in output
                for token in (
                    "badzipfile",
                    "cache entry",
                    "cached wheel",
                    "hashes do not match",
                    "invalid wheel",
                    "failed to extract",
                )
            ):
                return "cache_or_archive"
            if any(
                token in output
                for token in (
                    "conflicting dependencies",
                    "dependency conflict",
                    "no solution found",
                    "resolution impossible",
                    "resolutionimpossible",
                    "resolution too deep",
                    "resolutiontoodeep",
                )
            ):
                return "dependency_resolution"
            if any(
                token in output
                for token in (
                    "no matching distribution",
                    "not a supported wheel",
                    "requires-python",
                    "unsupported python",
                    "could not find a version that satisfies",
                )
            ):
                return "incompatible_or_unavailable"
            if any(token in output for token in ("access is denied", "permission denied", "operation not permitted")):
                return "permission"
            if any(
                token in output
                for token in (
                    "build failed",
                    "could not build wheels",
                    "failed building wheel",
                    "failed to build",
                    "subprocess-exited-with-error",
                )
            ):
                return "build"
            return "unknown"

        def metadata_versions(distribution_names: list[str]) -> dict[str, str | None]:
            if not distribution_names:
                return {}
            code = (
                "import importlib.metadata as m,json,sys;"
                "names=json.loads(sys.argv[1]);out={};"
                "exec(\"for n in names:\\n try: out[n]=m.version(n)\\n except m.PackageNotFoundError: out[n]=None\");"
                "print(json.dumps(out,sort_keys=True))"
            )
            try:
                completed = subprocess.run(
                    [str(python_executable), "-I", "-c", code, json.dumps(distribution_names)],
                    cwd=workspace,
                    capture_output=True,
                    timeout=30,
                    check=False,
                )
            except Exception:
                return {name: None for name in distribution_names}
            if completed.returncode != 0:
                return {name: None for name in distribution_names}
            for line in reversed(_decode_subprocess_output(completed.stdout).splitlines()):
                with suppress(json.JSONDecodeError):
                    payload = json.loads(line)
                    if isinstance(payload, dict):
                        return {name: payload.get(name) for name in distribution_names}
            return {name: None for name in distribution_names}

        def distribution_name(unit: list[str]) -> str | None:
            requirement = unit[1] if unit and unit[0] == "--editable" and len(unit) > 1 else unit[0]
            match = re.match(
                r"^\s*([A-Za-z0-9][A-Za-z0-9._-]*)(?=\s*@|\[|===|==|!=|~=|<=|>=|<|>|;|\s*$)",
                requirement,
            )
            return match.group(1) if match is not None else None

        def canonical_distribution(name: str | None) -> str:
            return re.sub(r"[-_.]+", "-", name or "").casefold()

        def is_unversioned_name(unit: list[str], name: str | None) -> bool:
            return bool(name and len(unit) == 1 and unit[0].strip().casefold() == name.casefold())

        def uv_module_version() -> str | None:
            try:
                completed = subprocess.run(
                    [str(python_executable), "-I", "-m", "uv", "--version"],
                    cwd=workspace,
                    capture_output=True,
                    timeout=30,
                    check=False,
                )
            except Exception:
                return None
            if completed.returncode != 0:
                return None
            return _decode_subprocess_output(completed.stdout).strip() or "available"

        def logical_requirement_lines(path: Path, seen: set[Path] | None = None) -> list[tuple[Path, str]]:
            resolved = path.resolve()
            visited = seen if seen is not None else set()
            if resolved in visited:
                raise ValueError(f"Recursive requirements include detected at {resolved}.")
            visited.add(resolved)
            logical: list[tuple[Path, str]] = []
            pending = ""
            for raw in resolved.read_text(encoding="utf-8", errors="strict").splitlines():
                stripped = raw.strip()
                if not stripped or stripped.startswith("#"):
                    continue
                pending = f"{pending} {stripped}".strip() if pending else stripped
                if pending.endswith("\\"):
                    pending = pending[:-1].rstrip()
                    continue
                logical.append((resolved.parent, pending))
                pending = ""
            if pending:
                logical.append((resolved.parent, pending))

            expanded: list[tuple[Path, str]] = []
            for parent, entry in logical:
                include_match = re.match(r"^(?:-r|--requirement)\s+(.+)$", entry, re.IGNORECASE)
                if include_match:
                    include_text = include_match.group(1).strip().strip("\"'")
                    include_path = (parent / include_text).resolve()
                    expanded.extend(logical_requirement_lines(include_path, visited))
                else:
                    expanded.append((parent, entry))
            visited.remove(resolved)
            return expanded

        sticky_options: list[str] = []
        requirement_units: list[list[str]] = []
        if requirements_file:
            requirements_path = _resolve(requirements_file, allow_missing=False, allow_external=True)
            option_pattern = re.compile(
                r"^(?:--(?:extra-index-url|find-links|index-url|no-binary|only-binary|trusted-host)"
                r"|--no-index|--pre|--prefer-binary)\b",
                re.IGNORECASE,
            )
            for parent, entry in logical_requirement_lines(requirements_path):
                constraint_match = re.match(r"^(?:-c|--constraint)\s+(.+)$", entry, re.IGNORECASE)
                if constraint_match:
                    constraint_text = constraint_match.group(1).strip().strip("\"'")
                    constraint_path = (parent / constraint_text).resolve()
                    sticky_options.extend(["--constraint", runtime_path(constraint_path)])
                    continue
                if option_pattern.match(entry):
                    sticky_options.extend(shlex.split(entry, posix=True))
                    continue
                hash_values = re.findall(
                    r"(?<!\S)--hash(?:=|\s+)(\S+)",
                    entry,
                    re.IGNORECASE,
                )
                requirement_text = re.sub(
                    r"(?<!\S)--hash(?:=|\s+)\S+",
                    "",
                    entry,
                    flags=re.IGNORECASE,
                ).strip()
                if not requirement_text:
                    raise ValueError(f"Requirements entry contains no package specification: {entry}")
                if requirement_text.startswith("-e "):
                    unit = ["--editable", requirement_text[3:].strip()]
                elif requirement_text.startswith("--editable "):
                    unit = ["--editable", requirement_text[len("--editable ") :].strip()]
                else:
                    unit = [requirement_text]
                unit.extend(f"--hash={value}" for value in hash_values)
                requirement_units.append(unit)
        for package in packages or []:
            package_text = str(package).strip()
            if package_text:
                requirement_units.append([package_text])
        if not requirement_units:
            raise ValueError("No installable package entries were found.")

        common_args = [str(item) for item in pip_args or [] if str(item).strip()]
        target_changing_options = (
            "--prefix",
            "--python",
            "--root",
            "--target",
            "--user",
            "-t",
        )
        for argument in common_args:
            lowered_argument = argument.casefold()
            if lowered_argument in target_changing_options or any(
                lowered_argument.startswith(f"{option}=") for option in target_changing_options if option.startswith("--")
            ):
                raise ValueError(f"pip_args may not redirect installation outside the selected environment: {argument}")
        common_args = [
            argument
            for argument in common_args
            if argument.casefold() not in {"--no-dependencies", "--no-deps", "--upgrade", "-u"}
        ]

        names = [name for name in (distribution_name(unit) for unit in requirement_units) if name]
        names = list(dict.fromkeys(names))
        versions_before = metadata_versions(names)
        target_uv_version = uv_module_version()
        package_results: list[dict[str, Any]] = []
        pending_units: list[tuple[list[str], str | None]] = []
        for unit in requirement_units:
            name = distribution_name(unit)
            before = versions_before.get(name) if name else None
            broken_uv = canonical_distribution(name) == "uv" and target_uv_version is None
            if before and not upgrade and is_unversioned_name(unit, name) and not broken_uv:
                package_results.append(
                    {
                        "requirement": unit[0],
                        "distribution": name,
                        "status": "already_present",
                        "version_before": before,
                        "version_after": before,
                        "verified": True,
                    }
                )
            else:
                pending_units.append((unit, name))

        uv_prefix: list[str] | None = (
            [str(python_executable), "-I", "-m", "uv"] if target_uv_version is not None else None
        )
        uv_python = target_native_python
        host_uv = _project_launch_command_executable("uv.exe", "uv") if target_is_windows else _project_launch_command_executable("uv", "uv.exe")
        if uv_prefix is None and host_uv:
            host_is_windows = str(host_uv).casefold().endswith(".exe")
            if host_is_windows == target_is_windows:
                uv_prefix = [str(host_uv)]
                uv_python = runtime_path(python_executable)

        uv_pending = next(
            (
                (unit, name)
                for unit, name in pending_units
                if canonical_distribution(name) == "uv"
            ),
            None,
        )
        active_installer = "none"
        if pending_units and uv_prefix is None and uv_pending is not None:
            unit, name = uv_pending
            pip_probe = run_process(
                [str(python_executable), "-I", "-m", "pip", "--version"],
                "pip",
                0,
                "uv_bootstrap_preflight",
                60,
            )
            if pip_probe["return_code"] != 0:
                ensurepip = run_process(
                    [str(python_executable), "-I", "-m", "ensurepip", "--upgrade"],
                    "ensurepip",
                    1,
                    "uv_bootstrap",
                    300,
                )
                if ensurepip["return_code"] != 0:
                    return {
                        "status": "uv_bootstrap_failed",
                        "installer": "ensurepip",
                        "environment": inspection.get("environment"),
                        "environment_kind": target_kind,
                        "python": str(python_executable),
                        "return_code": ensurepip["return_code"],
                        "returncode": ensurepip["return_code"],
                        "commands": commands,
                        "results": results,
                        "packages": package_results,
                        "verified": False,
                        "reason": "The target environment had neither runnable pip nor a successful ensurepip bootstrap.",
                    }
            bootstrap_base = [str(python_executable), "-I", "-m", "pip", "install", "--no-deps"]
            if upgrade:
                bootstrap_base.append("--upgrade")
            bootstrap_base.extend(sticky_options)
            bootstrap_base.extend(common_args)
            first = run_process([*bootstrap_base, *unit], "pip", 1, "uv_bootstrap")
            last = first
            first_class = failure_class(first)
            recoverable = first_class in {"build", "cache_or_archive", "transient_network", "unknown"} or (
                first_class == "dependency_resolution" and not upgrade and is_unversioned_name(unit, name)
            )
            if first["return_code"] != 0 and recoverable:
                recovery_flag = (
                    "--upgrade"
                    if first_class == "dependency_resolution" and not upgrade and is_unversioned_name(unit, name)
                    else "--no-cache-dir"
                )
                recovery = [*bootstrap_base]
                if recovery_flag not in recovery:
                    recovery.append(recovery_flag)
                last = run_process([*recovery, *unit], "pip", 2, f"uv_bootstrap_{first_class}")
            target_uv_version = uv_module_version() if last["return_code"] == 0 else None
            if last["return_code"] == 0 and target_uv_version is None and not upgrade:
                recovery = [*bootstrap_base, "--upgrade", *unit]
                last = run_process(recovery, "pip", 2, "uv_bootstrap_verification")
                target_uv_version = uv_module_version() if last["return_code"] == 0 else None
            after = metadata_versions([name]).get(name) if name else None
            uv_verified = bool(target_uv_version and after)
            package_results.append(
                {
                    "requirement": unit[0],
                    "distribution": name,
                    "status": "installed" if uv_verified else "failed",
                    "installer": "pip",
                    "version_before": versions_before.get(name) if name else None,
                    "version_after": after,
                    "verified": uv_verified,
                    "uv_version": target_uv_version,
                    "failure_class": None if uv_verified else failure_class(last),
                }
            )
            if not uv_verified:
                return {
                    "status": "uv_bootstrap_failed",
                    "installer": "pip",
                    "environment": inspection.get("environment"),
                    "environment_kind": target_kind,
                    "python": str(python_executable),
                    "return_code": last["return_code"] or 1,
                    "returncode": last["return_code"] or 1,
                    "commands": commands,
                    "results": results,
                    "packages": package_results,
                    "verified": False,
                    "reason": "uv was authorized but could not be installed and executed in the target environment.",
                }
            pending_units.remove(uv_pending)
            uv_prefix = [str(python_executable), "-I", "-m", "uv"]
            uv_python = target_native_python
            active_installer = "pip"

        if pending_units and uv_prefix is None:
            return {
                "status": "uv_unavailable",
                "installer": None,
                "environment": inspection.get("environment"),
                "environment_kind": target_kind,
                "python": str(python_executable),
                "return_code": 127,
                "returncode": 127,
                "commands": commands,
                "results": results,
                "packages": package_results,
                "verified": False,
                "reason": (
                    "uv is unavailable for the target environment. Ask the user to authorize installing uv in "
                    "that environment, or include uv in the requested package list."
                ),
            }

        final_return_code = 0
        for unit, name in pending_units:
            uv_base = [*uv_prefix, "pip", "install", "--python", uv_python, "--no-deps"]
            if upgrade:
                uv_base.append("--upgrade")
            uv_base.extend(sticky_options)
            uv_base.extend(common_args)
            first = run_process([*uv_base, *unit], "uv", 1)
            last = first
            first_class = failure_class(first)
            uv_attempts = 1
            recoverable = first_class in {"build", "cache_or_archive", "transient_network", "unknown"} or (
                first_class == "dependency_resolution" and not upgrade and is_unversioned_name(unit, name)
            )
            if first["return_code"] != 0 and recoverable:
                recovery_flag = (
                    "--upgrade"
                    if first_class == "dependency_resolution" and not upgrade and is_unversioned_name(unit, name)
                    else "--no-cache"
                )
                recovery = [*uv_base]
                if recovery_flag not in recovery:
                    recovery.append(recovery_flag)
                last = run_process([*recovery, *unit], "uv", 2, first_class)
                uv_attempts = 2
            active_installer = "uv"
            last_class = failure_class(last)
            if (
                last["return_code"] != 0
                and allow_pip_fallback
                and uv_attempts >= 2
                and last_class not in {"incompatible_or_unavailable", "permission"}
            ):
                pip_base = [str(python_executable), "-I", "-m", "pip", "install", "--no-deps"]
                if upgrade:
                    pip_base.append("--upgrade")
                pip_base.extend(sticky_options)
                pip_base.extend(common_args)
                last = run_process([*pip_base, *unit], "pip", 1, "after_repeated_uv_failure")
                pip_class = failure_class(last)
                pip_recoverable = pip_class in {"build", "cache_or_archive", "transient_network", "unknown"} or (
                    pip_class == "dependency_resolution" and not upgrade and is_unversioned_name(unit, name)
                )
                if last["return_code"] != 0 and pip_recoverable:
                    recovery_flag = (
                        "--upgrade"
                        if pip_class == "dependency_resolution" and not upgrade and is_unversioned_name(unit, name)
                        else "--no-cache-dir"
                    )
                    recovery = [*pip_base]
                    if recovery_flag not in recovery:
                        recovery.append(recovery_flag)
                    last = run_process([*recovery, *unit], "pip", 2, pip_class)
                active_installer = "pip"
                last_class = failure_class(last)
            after = metadata_versions([name]).get(name) if name and last["return_code"] == 0 else None
            verified = bool(name and after)
            package_results.append(
                {
                    "requirement": unit[0],
                    "distribution": name,
                    "status": "installed" if verified else "verification_failed" if last["return_code"] == 0 else "failed",
                    "installer": active_installer,
                    "version_before": versions_before.get(name) if name else None,
                    "version_after": after,
                    "verified": verified,
                    "failure_class": None if verified else last_class,
                }
            )
            if last["return_code"] != 0 or not verified:
                final_return_code = last["return_code"] or 1
                break

        all_verified = bool(package_results) and all(bool(item.get("verified")) for item in package_results)
        if final_return_code == 0 and not all_verified:
            final_return_code = 1
        final_status = "completed" if final_return_code == 0 and all_verified else "verification_failed" if all_verified is False and any(
            item.get("status") == "verification_failed" for item in package_results
        ) else "failed"
        return {
            "status": final_status,
            "installer": active_installer,
            "environment": inspection.get("environment"),
            "environment_kind": target_kind,
            "python": str(python_executable),
            "python_runtime": target_native_python,
            "return_code": final_return_code,
            "returncode": final_return_code,
            "commands": commands,
            "results": results,
            "packages": package_results,
            "verified": all_verified,
            "uv_version": uv_module_version(),
            "stdout": results[-1]["stdout"] if results else "",
            "stderr": results[-1]["stderr"] if results else "",
        }

